(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["co"] = {"ui":{"skip":"Andà à u cuntenutu","back":"← Torna à AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Sceglie una lingua","lang.search":"Circà lingue","lang.none":"Nisuna lingua currisponde","lang.notYet":"{name} ùn hè ancu traduttu","theme.aria":"Cambià tema: chjaru, scuru o neru","theme.toLight":"Passà à u tema chjaru","theme.toDark":"Passà à u tema scuru","theme.toBlack":"Passà à u tema neru (neru veru, dolce per i schermi OLED)","words.underline":"Sottulineà ste parolle nantu à a pagina","words.underlineHelp":"Passa sopra o tocca una parolla puntighjata per vede ciò ch'ella vole dì.","words.col.todo":"Carte sceglite per avà: a squadra principia cù queste dopu.","words.col.doing":"Una IA travaglia nantu à sta carta avà.","words.col.review":"Una IA hà finitu u travagliu; un'altra u verifica nanzu ch'ellu ghjunghji à tè.","words.col.verify":"Ti aspetta: pruvalu è dì s'ellu funziona.","words.col.team":"E to note o risposte, in attesa chì a squadra e piglii.","words.col.done":"Finita è accettata.","index.title":"AI-gile: a to squadra di sviluppu AI, nantu à una sola tavula","index.description":"AI-gile hè una tavula kanban per e squadre AI chì prugrammanu. Travaglianu mentre dorme; tù ricevi un picculu mucchjettu di cose à decide, pruvà è accettà.","hero.logoAlt":"Icona di a tavula AI-gile","hero.h1.html":"A to squadra di sviluppu AI, nantu à una sola&nbsp;tavula.","hero.alpha":"🐣 Pre-alfa chjosa","hero.alphaTitle":"Prestu è micca compiu: grazie di pruvallu!","hero.lede":"Custruiscenu mentre dorme. Ti svegli cù un mucchjettu cortu: qualchì dumanda, qualchì cosa à pruvà, un diamante viulettu o dui. Clic, accettatu, torna à u to caffè.","dl.windows":"App per Windows","dl.browser":"Eseguitela in u navigatore","dl.messenger":"📱 Messenger per u to telefuninu","dl.soon":"Prestu dispunibule","dl.notify":"🔔 Avvisami quandu s'apre","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, ma a squadra ùn hà mai bisognu di u caffè di a stand-up. (Face e stand-up listessu.)","pitch.h2":"AI-gile in tante parolle quant'è tù vo","pitch.lede":"Sceglie una lunghezza, da una parolla à 144. Ogni lunghezza hè una discrizzione propria, scritta per quella misura. Tira u cursore o usa e fraccette di a tastera.","pitch.rangeLabel":"Lunghezza in parolle","pitch.dice":"🎲 un'altra versione","pitch.words.one":"{n} parolla","pitch.words.other":"{n} parolle","pitch.letters.one":"{n} lettera","pitch.letters.other":"{n} lettere","pitch.chars.one":"{n} carattere","pitch.chars.other":"{n} caratteri","count.line.html.one":"{n} carta nantu à a tavula avà","count.line.html.other":"{n} carte nantu à a tavula avà","people.humans.html.one":"👥 {n} umanu","people.humans.html.other":"👥 {n} umani","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agenti","people.working.html.one":"⚡ {n} à u travagliu avà","people.working.html.other":"⚡ {n} à u travagliu avà","pre.title":"AI-gile : quì si custruisce qualcosa","pre.description":"Quì si custruisce qualcosa. Una tavula induve e squadre AI custruiscenu ciò chì dumandate, è v'amparanu strada facendu. Per avà, pre-alfa chjosa cù l'amichi.","pre.h1":"Quì si custruisce qualcosa. 🤫","pre.line":"Una tavula induve e squadre AI custruiscenu ciò chì dumandate, è v'amparanu strada facendu. Per avà, pre-alfa chjosa cù l'amichi.","pre.btn":"🔔 Avvisami quandu s'apre","pre.peek":"Daretu à u vetru : a vera tavula, in diretta. Ogni carta hè una striscia culurita.","pre.peekFake":"Daretu à u vetru : eccu cumu pare una tavula à u travagliu.","pre.night":"🌙 U guardianu di notte hè in carica · 😴 l'omu si riposa","features.aria":"Ciò chì face","f.pile.h":"Un mucchjettu per tè","f.pile.html":"<b>Per tè</b> riunisce tuttu ciò chì ti aspetta, in tutti i prugetti: dumande, cose à pruvà, travagli chì solu una persona pò fà. A to fila dice cio chì vene dopu è quantu tempu ci vole.","f.sleep.h":"Squadre chì travaglianu mentre dorme","f.sleep.p":"Ogni prugettu hà un capu è una squadra d'agenti AI. Lascia un cumentu nantu à una carta è a squadra si sveglia, face u travagliu è ti u rende cù i passi chì pò seguità ancu una persona stanca.","f.tester.h":"Un tester AI verifica prima","f.tester.p":"Nanzu chì qualcosa ti ghjunghje, un tester seguita i passi in una copia di l'app è mostra ciò chì hà vistu, cù una cattura di schermu. Sfoglia quelle chì sò passate è accetta cù un clic.","f.proof.h":"Prove, micca prumesse","f.proof.p":"Ogni cunsegna mostra ciò chì hè cambiatu: i fugliali, e differenze, e catture di schermu. Ùn ci hè bisognu d'apre ogni app per sapè s'ellu hè compiu.","f.chat.h":"Chjachjerà cù i to capi","f.chat.p":"Una barra à u stilu di Discord: una icona per prugettu, diamanti viulettu per ciò chì ti vole. Manda una idea à un capu; a trasforma in carte è in un pianu, cù un buttone ✅ Go.","f.tidy.h":"Si tene in ordine solu","f.tidy.p":"E carte parenti si unisconu in una, i tituli imbrugliati sò currettati, è un cuntrollu di i token tene u codice leggeru. Menu cose trà e quali passà, menu à pensà.","f.private.h":"Toiu, nantu à u to urdinatore","f.private.li1":"A tavula gira nantu à a to macchina è risponde solu à tè.","f.private.li2":"I missaghji privati trà e persone sò cifrati da un capu à l'altru.","f.private.li3":"Nisun contu, nisun tracciatore, nisun cookie.","f.lang.h":"In a to lingua","f.lang.p":"Più di 120 lingue, da l'olandese, u gallese è u giapponese finu à u pirata, Yoda è u klingon, cù un cambiu prestu in inglese per i termini di u mistieru.","f.service.h":"Da un'idea à un veru serviziu","f.service.p":"Hai custruitu cù l'IA qualcosa chì a ghjente adopra avà? Marcalu cum'è serviziu è u tavulinu t'aiuta à gestillu bè: cuntrolli di funziunamentu, una pagina di statu publica, incidenti cù un rapportu, cambiamenti chì anu bisognu d'un Si va, copie di salvezza verificate ogni ghjornu. L'Aiutu t'insegna ogni passu strada facendu.","msgr.h2":"AI-gile Messenger : a to squadra in stacca","msgr.p1":"Parla cù a to squadra IA senza apre a tavula. Chjachjareghja cù i capi di i to prughjetti è cù i to amichi, è vedi i passi di prova d'una scheda è rispondeli, tuttu da u to telefuninu.","msgr.p2":"Per accuppiallu, scanna un codice QR nantu à a to tavula. Prima volta ? Una chjachjarata demo simpatica ti face vede tuttu.","msgr.when":"Prima Android, dopu una versione web per i telefunini è l'iPhone.","msgr.who":"U capu di u to prughjettu","msgr.b1":"A currezzione di u modu scuru hè pronta. Voli i passi di prova ?","msgr.b2":"Iè, per piacè !","msgr.b3":"1. Apre Impostazioni. 2. Sceglie Scuru. Pare ghjustu ?","tl.aria":"Cronologia da a prima cunversazione à u pianu di strada","tl.h2":"Da a prima chjachjarata à ciò chì vene dopu","tl.lede":"Date è ore vere, in u to fusu orariu. Dopu à oghje hè u pianu, senza date prumesse.","tl.today":"Oghje","tl.planned":"previstu","tl.doing":"in corsu","tl.cards.one":"{n} carta","tl.cards.other":"{n} carte","join.h2":"Unisciti","join.lede":"AI-gile hè custruitu da un stranu barbutu cù l'AuDHD è qualchì battaglia cù a salute mentale, è da un gran numeru d'agenti pazienti. Hè privatu per avà, in una alfa chjosa cù l'amichi. Ti piacerebbe pruvallu quandu s'aprerà?","join.btn":"Signalà u to interessu","join.small":"Ti scriveremu un email, nunda più","footer.tag":"AI-gile. Nisun tracciatore, nisun cookie, nisun caffè di stand-up.","footer.licence":"Licenza d'impresa","footer.status":"Statu","footer.privacy":"Ciò chì guardemu","footer.thanks":"Chjame grazie à ChilledChat","form.sending":"Mandu in corsu…","form.failed":"Ùn hà micca fattu: ripruva più tardi.","form.offline":"Impussibule di ghjunghje à AI-gile: ripruva più tardi.","form.keep":"L'usemu solu per risponde ti, po u scancellemu. Nisun tracciatore, nisun cookie.","form.keepLink":"Ciò chì guardemu","interest.title":"AI-gile: avvisami quandu s'apre l'alfa","interest.description":"Lascia u to email per sapè quandu s'apre l'alfa chjosa o a beta di AI-gile.","interest.h1":"🔔 Avvisami quandu s'apre","interest.lede":"AI-gile hè in pre-alfa chjosa. Lascia u to email è ti scriveremu una volta, quandu ci serà un locu per tè.","interest.email":"U to email","interest.which":"Quale prova?","interest.alpha":"Alfa chjosa: prestu, grezza, tanti cambiamenti","interest.beta":"Beta: più stabile, dopu","interest.both":"L'una o l'altra, quella chì vene prima","interest.submit":"Mettimi nantu à a lista","interest.thanks":"Grazie! Sì nantu à a lista.","licence.title":"AI-gile: licenza d'impresa","licence.description":"Usi AI-gile in a to impresa? Dumanda una licenza d'impresa gratuita.","licence.h1":"📜 Licenza d'impresa","licence.lede":"Usi AI-gile à u travagliu? Dicci quale sì è ciò chì faci. S'ellu face un pocu di bè, a licenza hè gratuita.","licence.company":"Impresa","licence.website":"Situ web","licence.what":"Ciò chì faci","licence.how":"Cumu aiuta u mondu","licence.email":"Email","licence.submit":"Dumandà","licence.thanks":"Grazie! Ti risponderemu per email.","status.title":"Statu di AI-gile","status.h1":"Statu di AI-gile","status.quiet":"Tuttu tranquillu","status.intro":"AI-gile funziona avà? Sta pagina verifica u situ, u spartimentu di e tavule, e chjamate è u scaricamentu ogni 5 minuti.","status.up":"Funziona (hà rispostu in {ms} ms)","status.slow":"Ùn hà micca rispostu à l'ultima verificazione, ripruvemu","status.down":"In panna: ùn hà micca rispostu à l'ultime duie verificazioni","status.svc.web":"Situ web","status.svc.web.offers":"Stu situ: ciò ch'ellu hè AI-gile, è u furmulariu d'interessu","status.svc.boards":"Spartimentu di e tavule","status.svc.boards.offers":"Tavule publiche, messaghji trà amichi è invitazioni","status.svc.calls":"Chjamate","status.svc.calls.offers":"Voce, video è spartimentu di screnu in AI-gile","status.svc.download":"Scaricamentu","status.svc.download.offers":"L'installatore Windows è i liami d'invitazione","status.checking":"Verificà in corsu…","status.offline":"Impussibule di ghjunghje à u serviziu di statu avà (ripruvemu)","status.updated":"aghjurnatu {ago}","status.justNow":"à l'istante","status.min":"{n} min fà","status.hours":"{n} o fà","status.days":"{n} g fà","privacy.title":"AI-gile: ciò chì guardemu","privacy.h1":"Ciò chì guardemu","privacy.lede":"In breve: solu ciò chì tù ci mandi, è micca per longu.","privacy.only":"Solu ciò chì tù ci mandi: ciò chì tù scrivi in un furmulariu, cum'è u to email. Nunda altru nant'à tè.","privacy.sealed":"Hè sigillatu cusì chì u nostru servitore ùn u pò leghje: in u to navigatore prima ch'ellu parti (nantu à un navigatore più vechju, appena ch'ellu ghjunghje). Solu a nostra propria tavula u pò apre.","privacy.server":"Hè scancellatu da u servitore appena ch'ellu ghjunghje à a nostra tavula. Tuttu ciò chì ci hè sempre dopu à 30 ghjorni hè scancellatu quantunque.","privacy.board":"U guardemu nantu à a nostra tavula solu finu à ch'è no t'avemu rispostu, po u scancellemu quallà dinù.","privacy.none":"Nisun tracciatore, nisun cookie, nisuna analitica.","privacy.local":"A to lingua è a to scelta chjara o scura fermanu in u to propiu navigatore. Ùn ci sò mai mandate.","privacy.ask":"U voli sparitu più prestu? Rispondi à u nostru email è dicci la.","live.h2":"Guardate cumu hè custruitu, in diretta","live.caption":"Ogni carta hè piatta: videte a forma di u travagliu, micca e parolle.","live.watching.one":"in diretta: {n} chì guardanu","live.watching.other":"in diretta: {n} chì guardanu","live.last.now":"L'ultima carta hè stata spostata ghjustu avà","live.last.min.one":"L'ultima carta hè stata spostata {n} min fà","live.last.min.other":"L'ultima carta hè stata spostata {n} min fà","live.last.hour.one":"L'ultima carta hè stata spostata {n} ora fà","live.last.hour.other":"L'ultima carta hè stata spostata {n} ore fà","live.last.day.one":"L'ultima carta hè stata spostata {n} ghjornu fà","live.last.day.other":"L'ultima carta hè stata spostata {n} ghjorni fà","live.offline":"U tavulone in diretta piglia un pocu di risu. Turnate prestu.","live.cols":"Backlog|À fà|In corsu|Verificazione di a squadra|Per tè da testà|Per a squadra|Fattu","footer.models":"AI-gile face girà mudelli IA per tè. Ciò ch'elli dicenu è facenu hè soiu, dunque cuntrolla prima di fidà ti.","privacy.ai.h":"A parte IA","privacy.ai.models":"AI-gile hè a tavula. U travagliu hè fattu da mudelli IA d'altre sucietà, cum'è Claude, Codex è Gemini, nant'à i to conti.","privacy.ai.check":"Ciò ch'elli scrivenu è facenu vene da elli è pò esse sbagliatu. Cuntrolla prima di fidà ti o di pubblicà.","privacy.ai.files":"Cambianu i fugliali è eseguiscenu cumandi in i cartulari chì cunnetti. Fà una copia di salvezza.","privacy.ai.send":"Ciò chì dai à un mudellu va à a sucietà chì u face girà, sottu à e so cundizioni. E cundizioni è i costi di ogni sucietà s'applicanu.","privacy.ai.asis":"AI-gile hè una versione di pruva precoce, data cum'ella hè."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Delegatu."]},{"n":2,"texts":["Kanban robotica.","Agenti, urganizati.","Idee, custruite."]},{"n":3,"texts":["Kanban per robot.","Idee diventanu funzioni.","Kanban d'agenti gratuitu."]},{"n":5,"texts":["Tavula kanban guidata da agenti.","Tù scrivi carte. Agenti custruiscenu.","Gratuita, lucale, pruvata, un pocu scema."]},{"n":8,"texts":["Una tavula kanban gratuita induve travaglianu agenti AI.","Scrivi una idea. L'agenti a custruiscenu. Tù accetti.","Agile per una persona è tanti robot pazienti."]},{"n":13,"texts":["Una tavula kanban nantu à u to urdinatore induve l'agenti AI piglianu e carte.","Scrivi una idea. Una squadra d'agenti a custruisce. Un tester a verifica.","Gratuita, senza conti, senza tracciatori: una tavula, qualchì robot è tù à cumandà."]},{"n":21,"texts":["AI-gile hè una tavula kanban per travaglià cù agenti AI chì prugrammanu. Elli piglianu e carte; tù e pruvi è l'accetti.","Ogni prugettu hà un capu è una squadra d'agenti AI. Lascia un cumentu nantu à qualsiasi carta è a squadra si mette subitu à travaglià.","Una tavula persunale è gratuita, chì gira nantu à u to urdinatore. I travagliadori sò robot. Quellu chì dice iè sì tù."]},{"n":34,"texts":["Metti l'idee nantu à una tavula. Una squadra d'agenti AI e trasforma in funzioni chì marchjanu, e pruva è te e rende cù i passi per pruvalle. Nunda conta cum'è fattu finu à chì u dici tù.","AI-gile hè una tavula kanban fatta in casa chì Rich hà custruitu cù assai aiutu di l'agenti ch'ella gestisce oghje. Hè gratuita, gira nantu à u to urdinatore è hè spartuta cù l'amichi, micca venduta.","Imagina una tavula kanban nurmale, cù culonne da u Backlog à Fattu, ma induve e carte sò pigliate da agenti AI. Rapportanu l'avanzata, dumandanu quandu sò bluccati, è aspettanu sempre u to pollice in sù."]},{"n":55,"texts":["AI-gile hè una tavula kanban induve a squadra hè fatta d'agenti AI. Ogni prugettu hà un capu chì pianifica u travagliu è aiutanti chì u custruiscenu. Quandu una funzione hè pronta, un tester AI a pruva è face una cattura di schermu, poi ghjunghje in u to mucchjettu. Accettala, o lascia un cumentu è a rifaranu.","Hè natu cum'è u modu d'una persona di seguità parechje sessioni di prugrammazione AI à una volta, è hè criscutu finu à diventà una vera tavula. Gira nantu à a to macchina, ùn vole nisun contu, è ùn hà nisun tracciatore. Hè gratuita per l'amichi è i curiosi. Hè dinù incompiuta, dunque aspetta bordi grezzi è qualchì surpresa.","Eccu a versione onesta. Tù devi sempre avè l'idee, è devi sempre verificà i risultati. Ciò chì face AI-gile hè tuttu ciò chì ci hè trà i dui: tene e carte in ordine, sveglia l'agente ghjustu quandu lasci un cumentu, mostra esattamente ciò chì hè cambiatu, è mette tuttu in un mucchjettu cortu per tè."]},{"n":89,"texts":["AI-gile hè una tavula kanban gratuita chì fai girà nantu à u to propiu urdinatore. Invece di persone, ogni prugettu hà una squadra d'agenti AI: un capu chì trasforma e to idee in carte è in un pianu, è aiutanti chì piglianu e carte per ordine di prioriteta. Quandu qualcosa hè custruitu, un tester AI seguita i passi di prova è ti mostra ciò chì hà vistu. Poi aspetta in un mucchjettu chjamatu Per tè. L'accetti, o lasci un cumentu è a squadra pruva torna. Nunda ghjunghje mai à Fattu senza di tè.","Qualchì cosa chì forse ùn t'aspetti micca. Una guardia di notte tene piena a culonna À fà mentre dorme, sceglendu carte chì ùn anu bisognu d'una risposta da tè. Un cuntatore di token mostra quantu l'agenti anu adupratu oghje è sta settimana, è u No Token Mode li dice di piantà di spende. Pudi scrive à l'amichi, è i missaghji privati sò cifrati da un capu à l'altru. A tavula parla circa 120 lingue, cumprese l'olandese, u fiammingu, u pirata è u klingon. Nunda di tuttu què costa un centesimu, è nimu ùn prova à vendeti nunda.","AI-gile hè un picculu prugettu persunale, micca una sucietà. Rich vulia curà parechji prugetti di prugrammazione AI senza apre ogni app per verificalli, allora ellu è l'agenti anu custruitu una tavula per què, è dopu anu adupratu a tavula per custruisce u restu d'elli stessi. Hè in pre-alfa chjosa, chì vole dì ch'ella funziona, più o menu, per una manata d'amichi. Ùn ci hè pagina di prezzi, nè newsletter, nè pianu di crescita. S'ellu ti pare utile, pudi dumandà di pruvallu quandu s'aprerà un pocu di più."]},{"n":144,"texts":["AI-gile hè una tavula kanban per una persona è tanti agenti AI. Gira nantu à u to propiu urdinatore è hè compiamente gratuita. Aghjunghji prugetti, è ogni prugettu hà un capu è una squadra chjuca. Chjachjeri cù u capu, un pocu cum'è nantu à Discord, è discrivi una idea; u capu a trasforma in carte è in un pianu, poi aspetta ch'è tù prema Go. A squadra travaglia e carte per ordine di prioriteta, cù una linea di cumandi simplice fatta per i mudelli di lingua. Nanzu chì qualcosa ti torni, un tester AI seguita i passi in una copia di l'app è attacca una cattura di schermu. U travagliu compiu ghjunghje in u to mucchjettu cù i fugliali cambiati è a differenza. L'accetti, o lasci un cumentu è a squadra si sveglia è pruva torna. Solu tù pò spustà una carta in Fattu. Nisun contu, nisun tracciatore, nisun cookie, è tuttu stà nantu à u to urdinatore.","Una ghjurnata cù AI-gile, à pocu pressu. A sera lasci qualchì cumentu: stu buttone hè in u locu sbagliatu, quella lista duverebbe esse urdinata, puderiamu avè un modu scuru. Vai à durmite. L'agenti leghjenu i cumenti, facenu i cambiamenti, i pruvanu è i rendenu. Se À fà s'asciuga, a guardia di notte u riempie da u backlog cù carte chì ùn anu bisognu d'alcuna risposta da tè. À a mattina ci hè un mucchjettu cortu: una coppia di dumande è qualchì cosa à pruvà, ognuna cù passi chì pò seguità una persona insunnuliata è una cattura di schermu chì mostra ch'ella funziona. Clicchi, accetti e bone è rimandi u restu. Un cuntatore di token mostra ciò chì hà adupratu tuttu què, è u No Token Mode hè per e settimane magre. Poi fai colazione, chì l'agenti ùn ponu ancu aiutà à fà.","Prima, ciò chì AI-gile ùn hè micca. Ùn hè una startup, ùn hè in vendita, è nimu ùn raccoglie i to dati. Hè una tavula gratuita chì gira nantu à u to urdinatore, senza conti, senza tracciatori è senza cookie. Ciò ch'ella hè: un locu ordinatu per vede tutti i prugetti di prugrammazione AI à una volta, cù una squadra d'agenti chì face e carte è tù chì pigli e decisioni. Unisce e carte parenti, currege i tituli imbrugliati, è tene d'ochju quantu u codice firmeghja leggeru. Parla circa 120 lingue, da l'olandese è u fiammingu finu à u pirata è u klingon. L'amichi ponu scrivesi, in privatu è cifratu. Hè statu custruitu da Rich è un gran numeru d'agenti pazienti, soprattuttu aduprandusi. Hè in pre-alfa chjosa, dunque hè grezzu in certi lochi. S'ellu ti pare un spassu, dumanda cù gentilezza è forse entrerai prestu."]}],"quips":{"1":"Una parolla. Audace. Forse troppu audace.","3":"Trè parolle. Dighjà più onesta di a maiò parte di e pagine di prudotti.","8":"Ottu parolle. Sempre più corta d'una stand-up.","21":"E lunghezze sò story points, per via. Sicuru ch'elle sò.","55":"Cinquantacinque parolle. Dui carte sò state compie mentre leghji.","144":"Hè quella longa. Ùn ci hè 233. L'agenti sò andati à durmite."}},"timeline":{"first-idea.name":"A prima idea","first-idea.line":"A primissima cunversazione, nanzu ch'ellu esistessi qualsiasi codice.","first-board.name":"Prima tavula","first-board.line":"Una tavula chì seguita a so propria custruzzione: carte, culonne, tirà è lascià, prugetti.","team-roles.name":"Squadra è roli","team-roles.line":"Prufili d'agenti, mudelli di squadra, spazii è quale face ciò chì.","install.name":"Installazione è versioni","install.line":"Un zip chì un amicu pò installà, aghjurnamenti autumatichi, canali è ritornu in daretu.","usage-saver.name":"Risparmiu d'usu","usage-saver.line":"Misurà ciò chì costanu l'esecuzioni, tene u codice leggeru, risparmià u to limite.","friends.name":"Amichi è spartera","friends.line":"Missaghji privati, un relé cifratu, invitazioni, roli è prugetti spartuti.","languages.name":"Lingue","languages.line":"Ogni testu di schermu in un fugliale di lingua, cù l'olandese è u fiammingu prima.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester verifica prima ogni cunsegna è mostra ciò chì hà vistu.","website.name":"U situ web","website.line":"aigile.lol, l'anteprima è sta cronologia.","streaming.name":"Chat è streaming","streaming.line":"Discord, Twitch, OBS, modu streamer, GIF è emoji.","no-ai.name":"Edizione senza AI","no-ai.line":"Una tavula per quelli chì prugrammanu senza AI, è tavule pubbliche.","night-watch.name":"Guardia di notte","night-watch.line":"Un guardianu è un Scrum Master tenenu e squadre à u travagliu mentre dorme.","p-more.name":"Tuttu u restu","p-more.line":"Idee più chjuche chì aspettanu sempre u so turnu.","p-android.name":"Telefonu è Android","p-android.line":"Ghjunghje à a to tavula da un telefonu, poi una app Android nativa.","p-release.name":"Alfa è oltre","p-release.line":"Alfa chjosa, u situ in diretta, poi a beta.","p-languages.name":"Più lingue","p-languages.line":"130 lingue, è un modu d'immersione per quelli chì amparanu.","p-engines.name":"Più mutori AI","p-engines.line":"Sceglie Claude, Codex, Gemini, Copilot o Cursor per ogni agente.","p-pro.name":"Pratica prufessiunale","p-pro.line":"Etichette di risicu, porte di fusione, carte d'incidenti è paracarri.","p-self.name":"Curà di tè","p-self.line":"Modu stancu, rammentatori di cura di sè è 4:20.","p-servers.name":"Servitori è crescita","p-servers.line":"Paramettri glubali di i servitori, roli è pianificazione per crescere.","p-livestream.name":"Extra di streaming","p-livestream.line":"Chat di Twitch, emoji persunalizati è una vista pubblica in diretta."},"words":{"button":"📖 Termini di u mistieru","h":"📖 Parolle spiegate","intro":"Furmazione gratuita in lingua simplice : ogni parolla chì tù scontri da una prima idea à un serviziu da u quale a ghjente dipende, cù l'Agile, a custruzzione, a sicurità è u travagliu cù l'IA per strada.","search":"Circà una parolla…","none":"Nisuna parolla currisponde.","close":"Chjode","count":{"one":"{count} parolla","other":"{count} parolle"},"groups":[{"id":"idea","name":"💡 Idea è scuperta"},{"id":"plan","name":"🗺️ Pianificà u travagliu"},{"id":"agile","name":"🔁 Manere agili di travaglià"},{"id":"build","name":"🛠️ Custruisce"},{"id":"test","name":"🧪 Prove è qualità"},{"id":"change","name":"🔀 Cambià senza periculu"},{"id":"run","name":"🛎️ Gestisce un serviziu"},{"id":"sec","name":"🔒 Sicurità è vita privata"},{"id":"ai","name":"🤖 Travaglià cù l'IA"},{"id":"money","name":"💰 Soldi è licenze"}],"list":[{"id":"discovery","g":"idea","word":"Scuperta (Discovery)","text":"A fase di u principiu induve si capisce quale prublema vale a pena di risolve è per quale, nanzu di custruisce qualcosa.","also":["discovery phase","fase di scuperta"]},{"id":"problemstmt","g":"idea","word":"Enunciatu di u prublema","text":"Una o duie frasi chì dicenu quale hà un prublema, ciò ch'ellu hè è perchè conta, per ch'ognunu miri a listessa cosa.","also":["enunciati di u prublema","problem statements"]},{"id":"user","g":"idea","word":"Utilizatore","text":"Una persona chì usa ciò chì tù custruisci. U travagliu hè fattu per i so bisogni.","also":["utilizatori","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Parte interessata (Stakeholder)","text":"Chiunque tene à cumu va u travagliu o ne hè toccu, cum'è quelli chì u pagheghjanu, l'usanu o u sustenenu.","also":["parti interessate","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Una persona inventata ma realista chì raprisenta un tipu d'utilizatore, cusì a squadra si pò dumandà : « Per Sam, serà faciule ? »","also":["persone","personas"]},{"id":"userresearch","g":"idea","word":"Ricerca nant'à l'utilizatori","text":"Parlà cù e persone vere è guardà le per capì di chì anu bisognu, invece di induvinà.","also":["interviste d'utilizatori","user interviews"]},{"id":"journey","g":"idea","word":"Percorsu di l'utilizatore","text":"I passi chì una persona face per compie qualcosa, da quand'ella ne sente parlà finu à a fine, ancu fora di u to pruduttu. Disegnà lu mostra induve s'impantana.","also":["percorsi di l'utilizatori","user journeys","customer journey","percorsu di u cliente"]},{"id":"painpoint","g":"idea","word":"Puntu dulente (Pain point)","text":"Una cosa chì infastidisce o rallenta a ghjente oghje. I boni prudutti tolenu i punti dulenti.","also":["punti dulenti","pain points"]},{"id":"assumption","g":"idea","word":"Ipotesi di partenza (Assumption)","text":"Qualcosa chì tù credi ma ch'ùn hai ancu verificatu. Scrive e supposizioni mostra ciò chì ci vole à pruvà prima.","also":["supposizione","supposizioni","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipotesi","text":"Una supposizione chì tù pensi di verificà, cù ciò chì t'aspetti chì succeda, cum'è « a ghjente s'iscriverà s'è u primu mese hè gratuitu ».","also":["hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Sperimentu","text":"Una piccula prova pianificata per sapè s'ellu funziona un'idea, nanzu di scumette assai nant'à ella.","also":["sperimenti","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Pruva di cuncettu (PoC)","text":"Un tentativu rapidu è grezzu per vede s'è un'idea pò funziunà. Di solitu si ghjetta una volta chì si hà a risposta.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototipu","text":"Un mudellu primaticciu di u pruduttu, spessu imagine induve si pò cliccà, per pruvà l'idea nant'à a ghjente nanzu di custruisce la bè.","also":["prototipi","prototypes"]},{"id":"wireframe","g":"idea","word":"Schema di pagina (Wireframe)","text":"Un schizzu simplice di una schermata chì mostra induve vanu e cose, senza culori nè cuntenutu veru.","also":["wireframes","schemi di pagina"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Una imagine dettagliata di cumu parerà una schermata, cù culori è testu veri, ma nunda ùn funziona ancu.","also":["mockups","mock-up","mock-ups","mudellu graficu"]},{"id":"bizcase","g":"idea","word":"Casu d'affari (Business case)","text":"E ragiò per fà un prughjettu : ciò ch'ellu costa, ciò ch'ellu porta o risparmia, è i risichi.","also":["business cases","argumenti d'affari"]},{"id":"feasibility","g":"idea","word":"Fattibilità","text":"S'ellu si pò veramente custruisce è mantene una cosa cù u tempu, i soldi è e cumpetenze chì tù hai.","also":["feasibility","fattibile"]},{"id":"outcome","g":"idea","word":"Risultatu (Outcome)","text":"U cambiamentu chì tù voli per a ghjente, cum'è menu appuntamenti mancati. Conta più chè a quantità di cose chì custruisci.","also":["risultati","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Pruduzzione (Output)","text":"Qualcosa chì a squadra face, cum'è una schermata nova o un raportu. Fà la ùn vole micca dì per forza ch'ella aiuti qualchissia.","also":["pruduzzioni","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Misura di successu","text":"Un numeru chì ti dice s'è u travagliu hà righjuntu u so scopu, cum'è più persone chì compienu a so cumanda.","also":["misure di successu","success metrics"]},{"id":"kpi","g":"idea","word":"Indicatore chjave di prestazione (KPI)","text":"Un numeru impurtante chì tù guardi per vede s'è e cose vanu bè, cum'è l'iscrizzioni per settimana.","also":["KPI","KPIs","key performance indicator","indicatore chjave"]},{"id":"okr","g":"idea","word":"Obiettivi è risultati chjave (OKR)","text":"Una manera di fissà scopi : l'obiettivu dice ciò chì tù voli, è uni pochi di risultati chjave sò i numeri chì mostranu chì u scopu hè righjuntu.","also":["OKR","OKRs","obiettivi è risultati chjave"]},{"id":"product","g":"plan","word":"Pruduttu","text":"A cosa chì si custruisce è si mantene per i so utilizatori, cum'è una app, un situ web o un arnese.","also":["prudutti","products"],"noTip":1},{"id":"vision","g":"plan","word":"Visione di u pruduttu","text":"Una breve dichjarazione di quale u pruduttu aiuta è induve va à longu andà.","also":["product vision","vision statement"]},{"id":"po","g":"plan","word":"Pruprietariu di u pruduttu (PO)","text":"A persona chì decide ciò chì si custruisce è in quale ordine, cusì a squadra travaglia sempre nant'à ciò chì conta di più. In AI-gile sì tù.","also":["PO","product owners","pruprietarii di u pruduttu"]},{"id":"pm","g":"plan","word":"Capu pruduttu (PM)","text":"A persona chì veglia nant'à a direzzione di un pruduttu : quali prublemi risolve, per quale è perchè. PM pò dì ancu capu di prughjettu, dunque verifica di quale si tratta.","also":["capi pruduttu","product managers"]},{"id":"projmgr","g":"plan","word":"Capu di prughjettu","text":"A persona chì tene un prughjettu in tempu è in budget, seguitendu quale face chì è per quandu.","also":["capi di prughjettu","project managers"]},{"id":"roadmap","g":"plan","word":"Tabella di strada (Roadmap)","text":"Un pianu grezzu di ciò chì vene in i mesi chì venenu, in ordine. Mostra a direzzione, micca date esatte, è cambia mentre chì s'impara.","also":["roadmaps","pianu di strada"]},{"id":"milestone","g":"plan","word":"Tappa (Milestone)","text":"Un puntu di un prughjettu chì vale a pena di marcà, cum'è « prima versione in linea » o « 100 utilizatori ».","also":["tappe","milestones"]},{"id":"mvp","g":"plan","word":"Pruduttu minimu viabile (MVP)","text":"A più piccula versione di un pruduttu chì hè dighjà utile à a ghjente vera, per pudè amparà da elli prestu.","also":["MVP","MVPs","minimum viable product","pruduttu minimu"]},{"id":"requirement","g":"plan","word":"Esigenza","text":"Qualcosa chì u pruduttu finitu deve fà o esse.","also":["esigenze","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Perimetru (Scope)","text":"Ciò chì hè inclusu in u travagliu è, altrettantu impurtante, ciò chì ùn u hè micca.","also":["in scope","out of scope","drentu u perimetru","fora di u perimetru"]},{"id":"scopecreep","g":"plan","word":"Slittamentu di u perimetru (Scope creep)","text":"Quandu si aghjunghje sempre più à u travagliu pocu à pocu, senza chì nimu sia d'accordu nant'à u tempu o u costu in più, tantu ch'ellu ùn finisce mai.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Funzione (Feature)","text":"Una cosa chì u pruduttu pò fà per a ghjente, cum'è « reinizializà a to parolla d'ordine ».","also":["funzioni","features","funziunalità"],"noTip":1},{"id":"epic","g":"plan","word":"Epica (Epic)","text":"Un grande pezzu di travagliu, troppu grande per fà lu in una volta, dunque si taglia in carte più chjuche.","also":["epiche","epics"]},{"id":"story","g":"plan","word":"Storia d'utilizatore (User story)","text":"Un picculu pezzu di travagliu scrittu da u latu di l'utilizatore : « Cum'è cumpratore, vogliu tene u mo canistrellu, per pudè compie dopu ». Apre a cunversazione nant'à ciò chì ci vole à custruisce.","also":["storie d'utilizatore","user stories"]},{"id":"ac","g":"plan","word":"Criterii d'accettazione (AC)","text":"E verifiche chì una carta deve passà per esse cunsiderata fatta, cunvenute nanzu di principià, cum'è « u canistrellu hè sempre quì dopu ch'o mi scunnettu è mi ricunnettu ».","also":["acceptance criteria","criteriu d'accettazione"]},{"id":"task","g":"plan","word":"Cumpitu (Task)","text":"Un solu travagliu da fà, spessu un picculu passu di una storia più grande.","also":["cumpiti","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Un'altra parolla per una carta : un pezzu di travagliu o una dumanda, seguita da u principiu à a fine.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priurità","text":"Quantu hè impurtante o urgente qualcosa paragunatu à tuttu u restu, cusì u travagliu più impurtante hè fattu prima.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Ordine di priurità (Prioritisation)","text":"Mette u travagliu in ordine d'impurtanza. Una manera cumuna hè MoSCoW : Deve avè, Duveria avè, Puderia avè, Ùn averà micca sta volta.","also":["dà priurità","MoSCoW"]},{"id":"estimate","g":"plan","word":"Stima","text":"Una supposizione di quantu hè grande o longu un pezzu di travagliu. Hè una supposizione, micca una prumessa.","also":["stime","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Punti di storia (Story points)","text":"Una manera di induvinà a grandezza di u travagliu paragunendu e carte trà elle (« circa duie volte più grande chè quella ») invece di l'ore. Ùn sò micca per paragunà e squadre.","also":["story point"]},{"id":"tshirt","g":"plan","word":"Taglie di maglietta (T-shirt sizing)","text":"Induvinà a grandezza di u travagliu cum'è S, M, L o XL. Prestu è abbastanza bonu per a pianificazione di u principiu.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Poker di pianificazione (Planning poker)","text":"Un ghjocu per stimà : ognunu mostra una carta di grandezza à u listessu tempu, poi quellu chì hà datu u più altu è quellu chì hà datu u più bassu spieganu perchè.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dipendenza","text":"Quandu un pezzu di travagliu ùn pò micca principià o finisce finchè un altru ùn hè finitu.","also":["dipendenze","dependencies"]},{"id":"blocker","g":"plan","word":"Bluccu (Blocker)","text":"Tuttu ciò chì impedisce à u travagliu d'avanzà avà, cum'è una risposta chì manca o un arnese rottu.","also":["blucchi","blockers","impedimentu"]},{"id":"deadline","g":"plan","word":"Scadenza","text":"A data nanzu à a quale qualcosa deve esse finitu.","also":["scadenze","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Cunsegna (Deliverable)","text":"Qualcosa di cuncretu chì u travagliu produce è rimette, cum'è una pagina chì funziona o un raportu.","also":["cunsegne","deliverables"]},{"id":"forecast","g":"plan","word":"Previsione","text":"Una predizzione di ciò chì hè prubabile chì succeda, cum'è quandu u travagliu serà fattu, secondu ciò chì si sà finu à avà.","also":["previsioni","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metrica","text":"Tuttu ciò chì tù misuri è seguiti cù u tempu, cum'è e visite di pagina o u tempu ch'ellu ci vole à currege un prublema.","also":["metriche","metrics"]},{"id":"feedback","g":"plan","word":"Ritornu (Feedback)","text":"Ciò chì a ghjente ti dice di u to travagliu, bonu o gattivu. Riceve lu prestu è spessu hè u core di l'Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"A lista d'attesa d'idee è di travagliu micca ancu pianificati, cù u più impurtante in cima. Nunda quì hè travagliatu finu à chì passa in À fà."},{"id":"sprint","g":"agile","word":"Sprint","text":"Un periudu curtu è fissu di travagliu (spessu una o duie settimane, mai più d'un mese) cù un scopu è un inseme di carte accunsentite da compie.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un puntu rapidu di ogni ghjornu : ciò chì ogni membru di a squadra hà fattu, ciò ch'ellu face dopu, è ciò chì u ferma. In Scrum si chjama scrum di ogni ghjornu.","also":["standup","stand-ups","daily scrum","daily stand-up","riunione di ogni ghjornu","scrum di ogni ghjornu"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Una manera di travaglià induve e carte passanu da una colonna à l'altra di una tavula (cum'è À fà, In corsu, Fattu) è a squadra limita quantu hè in corsu à tempu, cusì u travagliu cuntinueghja à scorre."},{"id":"wip","g":"agile","word":"Limite WIP","text":"WIP vole dì work in progress, travagliu in corsu. Un limite WIP hè u numeru massimu di carte chì una colonna deve tene à tempu, cusì a squadra compie e cose nanzu di cumincià ne d'altre.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definizione di Fattu","text":"A lista corta di a squadra di ciò chì vole dì “compiu”, cum'è pruvatu è spiegatu, nanzu chì una carta ti sia data. A so gemella, a Definizione di Prontu, dice quandu una carta hè abbastanza chjara per principià.","also":["Definition of Ready","DoD","DoR","definizione di fattu"]},{"id":"retro","g":"agile","word":"Retro","text":"Un sguardu regulare in daretu à cumu travaglia a squadra, per mette si d'accordu nant'à una o duie cose da fà megliu a prossima volta. Accurtatura di retrospettiva. In AI-gile una retro prupone un cambiamentu à e manere di travaglià di a squadra, è tù dici Go o Micca ancu.","also":["retros","retrospettiva","retrospective"]},{"id":"swarm","g":"agile","word":"Sciame","text":"Tutti à bordu : parechje persone lascianu l'altru travagliu per currege inseme una cosa urgente finu à ch'ella sia risolta. In AI-gile ogni squadra aiuta nant'à un prughjettu, è l'altri prughjetti aspettanu intantu.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, a persona chì aiuta a squadra à travaglià bè : leva ciò chì a impedisce, tene e riunioni nantu à a strada è insegna bone abitudine, senza cumandà à nimu. In AI-gile u Lead Scrum Master vede e carte impantanate, spinghje e squadre è ti ricorda ciò chì aspetta, in ogni prughjettu.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Una manera di travaglià à picculi passi : custruisce un pocu, mostrà spessu risultati veri, amparà da ciò chì dice a ghjente è cambià u pianu strada facendu, invece di pianificà tuttu à l'iniziu.","also":["Agile development","agile ways of working","sviluppu agile","metodu agile"]},{"id":"manifesto","g":"agile","word":"Manifestu Agile","text":"Una breve dichjarazione scritta in u 2001 da creatori di software. Mette e persone, i risultati chì funziunanu, u travagliu strettu cù i clienti è a risposta à u cambiamentu nanzu à i piani pesanti è à a burucrazia.","also":["Agile Manifesto","Manifesto for Agile Software Development","Manifestu per u sviluppu agile"]},{"id":"waterfall","g":"agile","word":"Cascata (Waterfall)","text":"A manera più antica di travaglià : pianificà tuttu, poi custruisce tuttu, poi pruvà tuttu, una tappa dopu l'altra. I cambiamenti tardi sò difficiuli è cari.","also":["waterfall model","mudellu à cascata"]},{"id":"iteration","g":"agile","word":"Iterazione","text":"Un giru per custruisce qualcosa, verificà lu è megliurà lu. U travagliu Agile hè una catena di questi, è un sprint ne hè un tipu.","also":["iterazioni","iterations"]},{"id":"increment","g":"agile","word":"Incrementu","text":"Un pezzu novu chì funziona aghjuntu à u pruduttu in un sprint o in un giru di travagliu, chì si cumbina cù ciò chì ci era dighjà.","also":["incrementi","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Una manera Agile pupulare di travaglià : una piccula squadra travaglia in sprint curti versu un scopu, cù roli fissi è uni pochi di riunioni regulari per pianificà, verificà è megliurà."},{"id":"scrumteam","g":"agile","word":"Squadra Scrum","text":"U picculu gruppu chì face u travagliu in Scrum : un pruprietariu di u pruduttu, un Scrum Master è i sviluppatori.","also":["squadre Scrum","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Avvenimenti Scrum","text":"E riunioni regulari in Scrum : a pianificazione di u sprint, u scrum di ogni ghjornu, a rivista di u sprint è a retro. Assai ghjente le chjama ceremonie.","also":["ceremonie","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Pianificazione di u sprint","text":"A riunione à u principiu di un sprint induve a squadra si mette d'accordu nant'à perchè u sprint conta, quali carte piglià è cumu principià.","also":["riunione di pianificazione","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Scopu di u sprint","text":"Una frase chì dice à chì serve un sprint. I picculi cumpiti ponu cambià strada facendu, pur chì u scopu sia righjuntu.","also":["scopi di u sprint","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog di u sprint","text":"E carte scelte per u sprint attuale, cù u pianu di a squadra per fà le.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog di u pruduttu","text":"A lista cumpleta è ordinata di tuttu ciò chì si puderia custruisce per u pruduttu, u più impurtante in cima. Cambia sempre mentre chì s'impara.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Scopu di u pruduttu","text":"U risultatu più grande versu u quale u pruduttu travaglia, chì aiuta a squadra à sceglie ciò ch'ella face dopu.","also":["scopi di u pruduttu","product goals"]},{"id":"refinement","g":"agile","word":"Raffinamentu di u backlog","text":"Rivede regularmente u backlog per mette in ordine, taglià, ordinà è aghjunghje dettagli à e carte, per ch'elle sianu pronte à piglià. Si dice ancu backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Rivista di u sprint","text":"Una riunione à a fine di un sprint induve a squadra mostra ciò ch'ella hà compiu è sente ciò chì pensa a ghjente, per decide ciò chì vene dopu.","also":["riviste di u sprint","sprint reviews"]},{"id":"demo","g":"agile","word":"Dimostrazione (Demo)","text":"Mostrà u travagliu finitu chì funziona, in diretta, à e persone chì l'anu dumandatu.","also":["demos","dimostrazioni"],"noTip":1},{"id":"timebox","g":"agile","word":"Tempu fissu (Timebox)","text":"Una quantità di tempu fissa per qualcosa. Quand'ella hè finita, ti fermi, ancu s'ellu ùn hè micca tuttu fattu.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocità (Velocity)","text":"Quantu travagliu una squadra compie d'abitudine in un sprint, adupratu per pianificà quantu piglià a prossima volta. Ùn misura micca quantu a ghjente travaglia duru.","also":["team velocity","velocità di a squadra"]},{"id":"capacity","g":"agile","word":"Capacità","text":"Quantu travagliu a squadra pò piglià in un periudu, contu tenutu di e vacanze è di l'altri travagli.","noTip":1},{"id":"burndown","g":"agile","word":"Graficu di cunsumu (Burndown)","text":"Un graficu di u travagliu chì resta in un sprint, chì cala ghjornu per ghjornu. S'è a linea resta piatta, qualcosa hè impantanatu.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Graficu di prugressu (Burnup)","text":"Un graficu di u travagliu finitu chì sale cù u tempu, accantu à u totale pianificatu, per vede quandu ci ghjunghjerai.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Tavula Kanban","text":"A tavula stessa : una colonna per ogni tappa di u travagliu, cù e carte chì si movenu.","also":["Kanban boards","tavule Kanban"]},{"id":"pullsys","g":"agile","word":"Sistema à tirata (Pull system)","text":"Una manera di travaglià induve u travagliu novu principia solu quandu qualchissia hà locu per piglià lu, invece d'esse spintu nant'à un piattu dighjà pienu.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flussu (Flow)","text":"Quantu u travagliu scorre bè nant'à a tavula. Un bonu flussu vole dì chì e carte avanzanu invece di accatastassi.","also":["flow of work","flussu di travagliu"],"noTip":1},{"id":"leadtime","g":"agile","word":"Tempu totale (Lead time)","text":"Quantu tempu ci vole da quand'è qualchissia dumanda qualcosa finu à ch'ellu sia finitu.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Tempu di travagliu (Cycle time)","text":"Quantu tempu una carta piglia da quand'è u travagliu principia veramente nant'à ella finu à ch'ella sia finita.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Rendimentu (Throughput)","text":"Quante carte sò finite in una settimana, o in un altru periodu fissatu.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Strozzatura (Bottleneck)","text":"L'unica tappa induve u travagliu s'accatasta è rallenta tuttu ciò chì vene dopu, cum'è u collu strettu di una buttiglia.","also":["bottlenecks","strozzature"]},{"id":"swimlane","g":"agile","word":"Corsia (Swimlane)","text":"Una fila attraversu a tavula chì raggruppa e carte di un tipu, cum'è u travagliu urgente o e carte di una squadra.","also":["swimlanes","swim lane","corsie"]},{"id":"lean","g":"agile","word":"Lean","text":"Una manera di travaglià chì taglia i sprechi (tuttu ciò chì ùn aiuta micca u cliente) è tene u travagliu in muvimentu."},{"id":"waste","g":"agile","word":"Sprecu (Waste)","text":"In Lean, tuttu ciò chì piglia sforzu ma ùn aiuta micca u cliente, cum'è aspettà, rifà o custruisce cose chì nimu usa.","noTip":1},{"id":"kaizen","g":"agile","word":"Migliuramentu cuntinuu","text":"Diventà un pocu megliu tuttu u tempu cù picculi cambiamenti regulari, poi verificà s'elli anu aiutatu. E retro ne sò una manera. Si dice ancu kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Squadra autorganizata","text":"Una squadra chì decide da sè cumu fà u travagliu, invece di riceve ordini passu per passu.","also":["self-organising","self-managing team","autorganizata"]},{"id":"crossfunc","g":"agile","word":"Squadra pluridisciplinare","text":"Una squadra chì hà tutte e cumpetenze chì ci vole per compie u travagliu da sè, cum'è disegnu, custruzzione è prove.","also":["cross-functional","pluridisciplinare"]},{"id":"spike","g":"agile","word":"Spike","text":"Una breve ricerca à tempu fissu per risponde à una dumanda nanzu d'impegnassi in u veru travagliu.","also":["spikes","ricerca corta"]},{"id":"rework","g":"agile","word":"Rifacimentu (Rework)","text":"Rifà un travagliu perchè ùn era micca ghjustu a prima volta.","also":["reworked"]},{"id":"safe","g":"agile","word":"Agile à grande scala (SAFe)","text":"Manere d'usà l'Agile in parechje squadre d'una grande urganizazione. SAFe (Scaled Agile Framework) ne hè un esempiu cunnisciutu.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"U cartulare di u prughjettu cù u codice è tutta a so storia di commit. Pò stà nant'à u to urdinatore, nant'à GitHub, o tramindui.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una linea di travagliu à parte in u codice, per pudè fà cambiamenti senza tuccà a versione principale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Una istantanea salvata di u codice, cù una nota corta di ciò chì hè cambiatu. Pudi sempre turnà à una.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Mandà e to istantanee salvate (commit) da st'urdinatore à a copia sparta in linea, cum'è GitHub, per ch'elle sianu salvate è chì l'altri e possinu piglià."},{"id":"merge","g":"build","word":"Merge","text":"Unisce i cambiamenti d'un branch in un altru, di solitu torna in a versione principale."},{"id":"pr","g":"build","word":"Pull request","text":"Dumandà chì i cambiamenti d'un branch sianu verificati è uniti à a versione principale. Certi siti a chjamanu merge request.","also":["PR","PRs","merge request","dumanda di fusione"]},{"id":"refactor","g":"build","word":"Refactor","text":"Mette in ordine u codice senza cambià ciò chì face : schedarii più chjuchi, nomi più chjari, menu ripetizioni."},{"id":"bug","g":"build","word":"Bug","text":"Qualcosa chì ùn funziona micca cum'ellu duverebbe.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revisione tra pari","text":"Un secondu paru d'ochji : qualchissia altru chè l'autore verifica u travagliu nanzu ch'ellu ghjunghji à tè, cusì menu sbaglii passanu. In AI-gile un'altra IA verifica ogni carta.","also":["revisione di u codice","peer review","code review"]},{"id":"code","g":"build","word":"Codice (Code)","text":"L'istruzzioni scritte chì dicenu à un urdinatore ciò ch'ellu deve fà. Si dice ancu codice fonte.","also":["source code","codice fonte"],"noTip":1},{"id":"proglang","g":"build","word":"Lingua di prugrammazione","text":"Una lingua per scrive codice, cum'è JavaScript, Python o Java. Ognuna s'adatta à travagli diversi.","also":["lingue di prugrammazione","programming language","programming languages"]},{"id":"developer","g":"build","word":"Sviluppatore (dev)","text":"Qualchissia chì scrive è cambia u codice. Si dice ancu prugrammatore o ingegnere di software.","also":["sviluppatori","developer","developers","programmer","programmers","software engineer","prugrammatore"]},{"id":"software","g":"build","word":"Software","text":"I prugrammi chì giranu nant'à l'urdinatori è i telefonini, à u cuntrariu di e macchine stesse (l'hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Accurtatura di applicazione : un prugramma chì a ghjente usa per fà qualcosa, nant'à un telefuninu, un urdinatore o in un navigatore web.","also":["apps","application","applications","applicazione"],"noTip":1},{"id":"webapp","g":"build","word":"App web","text":"Una app chì gira in un navigatore web, dunque ùn ci hè nunda à installà.","also":["web apps","web application","applicazione web"]},{"id":"frontend","g":"build","word":"Front end","text":"A parte d'una app chì tù vedi è nant'à quale clicchi : e schermate, i buttoni è e parolle, spessu in u to navigatore.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"A parte piattata d'una app, chì tene i dati è face u travagliu quandu tù clicchi qualcosa, cum'è verificà a to parolla d'ordine.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Travaglià à tempu nantu à u front end è u back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Interfaccia d'utilizatore (UI)","text":"Ciò chì una persona vede è usa nant'à u schermu : a disposizione, i buttoni, i menu è u testu.","also":["UI","user interface","interfaccia"]},{"id":"ux","g":"build","word":"Sperienza d'utilizatore (UX)","text":"Cumu si sente usà qualcosa : faciule, chjaru è piacevule, o cunfusu è lentu.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibilità (a11y)","text":"Fà cose chì tutti ponu usà, ancu e persone chì ùn ci vedenu micca bè, ùn ponu micca usà u topu o usanu un lettore di schermu.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Disegnu adattativu (Responsive)","text":"Fà pagine chì s'adattanu è funziunanu bè nant'à ogni grandezza di schermu, da u telefuninu à un grande monitore.","also":["responsive design","adattativu"]},{"id":"designsys","g":"build","word":"Sistema di disegnu (Design system)","text":"Un kit cumunu di culori, caratteri, buttoni è regule, cusì ogni schermata pare è si cumporta listessu.","also":["design systems","sistemi di disegnu"]},{"id":"architecture","g":"build","word":"Architettura","text":"A forma d'inseme d'un sistema : quali sò e parti principali è cumu parlanu trà elle."},{"id":"database","g":"build","word":"Basa di dati (DB)","text":"Un magazinu urganizatu d'infurmazioni, cum'è un fogliu di calculu assai putente chì l'app pò leghje è cambià.","also":["database","databases","DB","basa di dati"]},{"id":"schema","g":"build","word":"Schema di a basa di dati","text":"A disposizione d'una basa di dati : quali tabelle d'infurmazioni hà è ciò chì entre in ognuna.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Accurtatura di structured query language : a lingua chì si usa per dumandà infurmazioni à parechje basi di dati o per cambià le.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Dati","text":"L'infurmazioni tenute da un urdinatore, cum'è nomi, cumande o impostazioni.","also":["dati","data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Servitore (Server)","text":"Un urdinatore sempre accesu chì risponde à e dumande d'altri urdinatori, cum'è mandà una pagina web quandu tù a visiti.","also":["servitori","server","servers"]},{"id":"client","g":"build","word":"Cliente (Client)","text":"U latu chì dumanda qualcosa, di solitu u to navigatore o a to app, chì parla cù un servitore. In u cummerciu vole dì ancu solu un cliente.","also":["clienti","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Accurtatura di application programming interface : un menu fissu di dumande chì un prugramma pò fà à un altru, cum'è dumandà à un serviziu meteo e previsioni d'oghje.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Puntu d'accessu (Endpoint)","text":"Una voce di u menu d'una API : un indirizzu web chì un prugramma pò chjamà per riceve o mandà qualcosa.","also":["endpoint","endpoints","punti d'accessu"]},{"id":"integration","g":"build","word":"Integrazione","text":"Cunnette dui sistemi per ch'elli travaglinu inseme, cum'è a to buttega chì manda e cumande à u to prugramma di cuntabilità.","also":["integrazioni","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Un messaghju chì un sistema manda à un altru da sè à u mumentu ch'ellu succede qualcosa, cum'è « pagamentu ricevutu ».","also":["webhooks"]},{"id":"library","g":"build","word":"Libreria","text":"Codice prontu scrittu da qualchissia altru, chì tù poi riusà invece di scrive lu da tè.","also":["librerie","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Una struttura pronta per custruisce una app chì decide una bona parte di cumu hè dispostu u codice, cum'è l'ossatura d'una casa chì tù poi empie.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Kit di sviluppu (SDK)","text":"Una scatula d'arnesi, codice è esempii per fà software per una piattaforma o un serviziu.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Dipendenza di software","text":"Una libreria o un arnese di chì u to codice hà bisognu per funziunà. Tene le à ghjornu hè impurtante per a sicurità.","also":["software dependency","software dependencies","dipendenze di software"]},{"id":"package","g":"build","word":"Pacchettu","text":"Un fasciu di codice prontu chì tù poi installà è usà in un prughjettu.","also":["pacchetti","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Gestore di pacchetti","text":"Un arnese chì piglia è mette à ghjornu i pacchetti da i quali dipende u to codice. npm ne hè unu di i più cumuni.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"L'arnese u più adupratu per tene a storia di i cambiamenti di u codice, in forma di commit è di branch."},{"id":"github","g":"build","word":"GitHub","text":"Un situ web chì tene i repo Git in linea, cusì e squadre ponu sparte u codice, rivede i cambiamenti è seguità u travagliu."},{"id":"vcs","g":"build","word":"Cuntrollu di versione","text":"Tene una storia cumpleta di ogni cambiamentu di i schedarii, per vede quale hà cambiatu cosa è tornà in daretu s'ellu ci vole. Git u face.","also":["version control","source control","version control system","cuntrollu di fonte"]},{"id":"clone","g":"build","word":"Clone (copia)","text":"Fà a to propria copia cumpleta d'un repo, cù a so storia, nant'à u to urdinatore.","also":["clone","cloned","cloning","clonà"]},{"id":"pull","g":"build","word":"Pull","text":"Piglià l'ultimi commit da a copia sparta (cum'è GitHub) nant'à u to urdinatore. L'uppostu di push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Ramu principale (Main)","text":"A versione ufficiale di u codice da quale tutti partenu, chjamata spessu main o master.","also":["main branch","master branch","ramu principale"]},{"id":"conflict","g":"build","word":"Cunflittu di fusione (Merge conflict)","text":"Quandu dui cambiamenti toccanu e listesse linee in modi sfarenti, cusì l'urdinatore ùn pò unisce li è una persona deve sceglie.","also":["merge conflict","merge conflicts","cunflitti di fusione"]},{"id":"diff","g":"build","word":"Diff","text":"Una vista chì mostra esattamente ciò chì hà cambiatu trà dui versioni : linee aghjunte è linee tolte.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"A to propria copia di u repo di qualchissia altru, chì tù poi cambià senza toccà u soiu.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Un cortu prugramma chì face un travagliu da sè, cum'è mette in ordine i schedarii o lancià l'app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Compilazione (Build)","text":"Trasfurmà u codice in qualcosa prontu à girà, o u risultatu stessu prontu à girà.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Compilà","text":"Traduce u codice scrittu da e persone in una forma chì l'urdinatore pò eseguisce direttamente.","also":["compile","compiler","compilatore"]},{"id":"cli","g":"build","word":"Linea di cumanda (CLI)","text":"Una finestra di testu induve si scrive l'istruzzioni per l'urdinatore invece di cliccà. Si dice ancu terminale.","also":["command line","command-line","CLI","terminal","terminale"]},{"id":"config","g":"build","word":"Cunfigurazione (config)","text":"L'impostazioni chì cuntrollanu cumu si cumporta u software, tenute fora di u codice per ch'elle sianu faciuli à cambià.","also":["config","configuration","cunfigurazione"],"noTip":1},{"id":"envvar","g":"build","word":"Variabile d'ambiente","text":"Una impostazione data à un prugramma quand'ellu parte, spessu per indirizzi o parolle d'ordine per ch'elle ùn sianu micca scritte in u codice.","also":["environment variable","environment variables","env var","variabili d'ambiente"]},{"id":"debugging","g":"build","word":"Debugging","text":"Circà perchè qualcosa ùn funziona micca, è currege lu.","also":["debug","debugged","currezzione d'errori"]},{"id":"pairing","g":"build","word":"Prugrammazione à dui","text":"Duie persone (o una persona è una IA) chì travaglianu nant'à u listessu codice inseme, una chì scrive è l'altra chì verifica.","also":["pair programming","pairing","prugrammazione in coppia"]},{"id":"docs","g":"build","word":"Documentazione (docs)","text":"Spiegazioni scritte di cumu funziona qualcosa o cumu usà lu.","also":["documentation","docs","documentazione"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"U primu schedariu da leghje in un repo : ciò ch'ellu hè u prughjettu è cumu fà lu girà.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistema ereditatu (Legacy)","text":"Un sistema più anticu sempre in usu è difficiule da cambià, spessu perchè pochi u capiscenu sempre.","also":["legacy system","legacy systems","legacy code","sistema anticu"]},{"id":"techdebt","g":"build","word":"Debitu tecnicu","text":"Scurciatoie chì facenu guadagnà tempu avà ma rallentanu i cambiamenti dopu, cum'è un prestitu chì face interessi. A rifattura u rimborsa.","also":["technical debt","tech debt","debitu tecnicu"]},{"id":"test","g":"test","word":"Test","text":"Una verifica chì qualcosa funziona cum'ellu deve. Certe prove l'urdinatore e face da sè ogni volta chì u codice cambia ; l'altre sò tù chì pruvi una carta finita nanzu d'accettà la.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Accurtatura di quality assurance, assicuranza di qualità : tuttu ciò chì si face per esse sicuri chì u travagliu sia ghjustu nanzu ch'ellu passi in linea. In AI-gile vole dì e verifiche automatiche : quandu u QA hè rossu, qualcosa hà fiascatu, è ùn pò micca passà in linea finu à ch'ellu sia currettu.","also":["cuntrolli di qualità","garanzia di qualità","quality checks"]},{"id":"testpile","g":"test","word":"Pila di prove","text":"E carte compie chì aspettanu chì tù e provi, una dopu l'altra. Accetta ne una o rimandala cù una nota, è vene a seguente.","also":["pile di prove","test pile"]},{"id":"autotest","g":"test","word":"Prova automatica","text":"Una verifica chì l'urdinatore face da sè ogni volta chì u codice cambia, per truvà i sbaglii prestu.","also":["automated test","automated tests","automatic tests","prove automatiche"]},{"id":"manualtest","g":"test","word":"Prova manuale","text":"Una persona chì prova u travagliu à manu per vede s'ellu si cumporta cum'ellu deve.","also":["manual test","manual tests","manual testing","prove manuali"]},{"id":"unittest","g":"test","word":"Prova unitaria (Unit test)","text":"Una piccula verifica automatica di un solu picculu pezzu di codice, da sè.","also":["unit test","unit tests","prove unitarie"]},{"id":"integtest","g":"test","word":"Prova d'integrazione","text":"Una verifica chì parechje parti funzionanu bè inseme, micca solu una à una.","also":["integration test","integration tests","prove d'integrazione"]},{"id":"endtoend","g":"test","word":"Prova da capu à fine (E2E)","text":"Una prova chì agisce cum'è un utilizatore veru da u principiu à a fine, cum'è iscriversi, cumprà è pagà.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"Prova d'accettazione (UAT)","text":"E persone chì anu dumandatu u travagliu u pruvanu elle stesse è dicenu s'ellu face ciò chì li serve. A pila di prove d'AI-gile ne hè a so versione.","also":["UAT","acceptance testing","prova d'accettazione utilizatore"]},{"id":"regression","g":"test","word":"Regressione","text":"Qualcosa chì funziunava ma s'hè rottu dopu un cambiamentu. E prove di regressione verificanu chì e cose di prima funzionanu sempre.","also":["regressions","regression test","regression tests","regression testing","regressione"]},{"id":"smoke","g":"test","word":"Prova di fumu (Smoke test)","text":"Una verifica assai rapida chì e cose principali funziunanu almenu, per esempiu subitu dopu chì un cambiamentu passa in linea. S'ella falla, fermati è guarda.","also":["smoke test","smoke tests","prova di fumu"]},{"id":"exploratory","g":"test","word":"Prova esplorativa","text":"Pruvà u pruduttu liberamente è stuzzicà lu in modi diversi, per truvà prublemi chì e verifiche pianificate ùn truverianu micca.","also":["exploratory testing","exploratory test","exploratory tests","prove esplorative"]},{"id":"testcase","g":"test","word":"Casu di prova","text":"Un scenariu scrittu da pruvà : i passi, è ciò chì deve succede.","also":["test case","test cases","casi di prova"]},{"id":"coverage","g":"test","word":"Cupertura di e prove","text":"Quantu codice hè verificatu da prove automatiche. Più cupertura hè di solitu più sicura, ma una cupertura alta sola ùn pruva micca chì u codice funziona bè.","also":["test coverage","code coverage","cupertura di u codice"]},{"id":"testdata","g":"test","word":"Dati di prova","text":"Infurmazioni d'esempiu inventate, aduprate durante e prove, per ùn espone i dati privati di nisuna persona vera.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Casu limite","text":"Una situazione insolita à i limiti, cum'è un furmulariu vacuu o un nome cù un apostrofu, induve e cose si rompenu spessu.","also":["edge case","edge cases","casi limite"]},{"id":"happypath","g":"test","word":"Percorsu felice (Happy path)","text":"U percorsu nurmale induve tuttu va bè. E bone prove pruvanu ancu i percorsi menu felici."},{"id":"perftest","g":"test","word":"Prova di prestazione","text":"Verificà quantu hè rapidu qualcosa è cumu regge sottu à a pressione.","also":["performance testing","performance test","performance tests","prove di prestazione"]},{"id":"loadtest","g":"test","word":"Prova di carica","text":"Verificà cumu un sistema regge quandu assai persone l'usanu à tempu.","also":["load testing","load test","load tests","prove di carica"]},{"id":"sectest","g":"test","word":"Prova di sicurità","text":"Circà e debulezze chì puderianu lascià qualchissia abusà d'un sistema o vede ciò ch'ellu ùn deve micca.","also":["security testing","security test","security tests","prove di sicurità"]},{"id":"accesstest","g":"test","word":"Prova d'accessibilità","text":"Verificà chì e persone cù capacità sfarenti ponu usà u pruduttu, ancu cù un lettore di schermu o solu cù una tastera.","also":["accessibility testing","accessibility test","prove d'accessibilità"]},{"id":"linting","g":"test","word":"Linting","text":"Una verifica automatica chì vede sbaglii prubabili è stile disurdinatu in u codice, cum'è un currettore ortograficu per i prugrammi.","also":["linter","lint"]},{"id":"static","g":"test","word":"Analisi statica","text":"Verificà u codice per truvà prublemi leghjendu lu automaticamente, senza eseguisce lu.","also":["static analysis","static code analysis","analisi di codice"]},{"id":"flaky","g":"test","word":"Prova instabile (Flaky test)","text":"Una prova chì qualchì volta passa è qualchì volta falla senza ragione chjara, dunque ùn ci si pò micca fidà cumpletamente.","also":["flaky test","flaky tests","prove instabili"]},{"id":"repro","g":"test","word":"Riprodue (repro)","text":"Fà succede torna un prublema apposta seguitendu i listessi passi, per pudè studià lu è currege lu. Scrive quelli passi hè a parte più utile d'un raportu di prublema.","also":["repro","reproduce","steps to reproduce","passi per riprodue"]},{"id":"severity","g":"test","word":"Gravità","text":"Quantu hè grave l'effettu d'un prublema, da un picculu fastidiu à tuttu chì si ferma.","also":["severity","severity level","livellu di gravità"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copià una nova versione di u software nant'à l'urdinatori chì u facenu girà, cum'è una copia di prova o u serviziu in linea."},{"id":"release","g":"change","word":"Versione","text":"Un pacchettu cù un nome di travagliu compiu chì passa in pruduzzione inseme, cù note brevi nant'à ciò chì hà cambiatu. 🚀 Versioni scrive e note à partesi da e carte fatte.","also":["versioni","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Tornà à l'ultima versione chì funziunava quandu una nova face prublemi. In AI-gile, Roll back riunisce in una sola lista i passi per annullà scritti nant'à ogni cambiamentu.","also":["ritornu in daretu","rivolta","roll back"]},{"id":"live","g":"change","word":"Pruduzzione","text":"A versione vera chì a ghjente adopra, à u cuntrariu d'una copia per pruvà e cose. I sviluppatori a chjamanu ancu production o “live”.","also":["in diretta","production","live"],"noTip":1},{"id":"change","g":"change","word":"Cambiamentu","text":"Un cambiamentu prughjettatu nant'à qualcosa chì a ghjente ci conta, scrittu prima: chì, perchè, u risicu, quandu, è cumu disfallu. Principiane unu cù 🔀 Dumandà un cambiamentu.","also":["cambiamenti","dumanda di cambiamentu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risicu","text":"Qualcosa chì puderia andà male, cù un puntu secondu quantu hè prubabile è quantu seria gravu. ⚠️ Risichi i tene in una lista, u puntu più altu prima, ognunu cù una data per fighjallu torna.","also":["risichi","registru di i risichi","risk"]},{"id":"chgwin","g":"change","word":"Finestra di cambiamentu","text":"L'ore quandu i cambiamenti ponu passà in pruduzzione, cum'è un marti di sera tranquillu. Fora d'una finestra una carta di cambiamentu ùn pò esse compia, eccettu s'ella hè un'urgenza.","also":["finestre di cambiamentu","change window"]},{"id":"gonogo","g":"change","word":"Si va / Ùn si va","text":"Una ultima verifica subitu nanzu chì un cambiamentu passi in linea : ogni persona chì deve appruvà dice Si va o Ùn si va. Si va avanti solu quandu tutti dicenu Si va.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Appruvazione","text":"Aspettà un sì nanzu chì u travagliu principii. Una carta prupusta da un amicu, o un cambiamentu, aspetta in ✅ Appruvazioni finchè tù ùn l'appruvi o ùn la ricusi.","also":["appruvazioni","approval"]},{"id":"quiettime","g":"change","word":"Tempu tranquillu","text":"Un periudu, cum'è durante una diretta, una dimostrazione o di notte, quandu nunda ùn passa in linea. E squadre cuntinueghjanu à travaglià è à pruvà, ma u passaghju in linea aspetta a fine. Altrò si chjama change freeze.","also":["tempi tranquilli","ghjelu di i cambiamenti","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Una manera di travaglià induve e persone chì custruiscenu u software è quelle chì u facenu girà travaglianu cum'è una sola squadra, cù assai automatizazione, cusì i cambiamenti passanu in linea spessu è senza risichi."},{"id":"cicd","g":"change","word":"CI/CD (integrazione è cunsegna cuntinue)","text":"I cambiamenti di tutti sò uniti spessu in a versione principale è verificati automaticamente ogni volta (integrazione cuntinua), cusì u software hè sempre prontu à passà in linea cù un clic (cunsegna cuntinua).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","integrazione cuntinua","cunsegna cuntinua"]},{"id":"contdeploy","g":"change","word":"Implementazione cuntinua","text":"Un passu di più chè a cunsegna cuntinua : ogni cambiamentu chì passa e verifiche passa in linea da sè, senza buttone da appughjà.","also":["continuous deployment","continuous deployments","implementazione automatica"]},{"id":"pipeline","g":"change","word":"Catena di pruduzzione (Pipeline)","text":"A seria automatica di passi chì un cambiamentu face per passà in linea, cum'è compilà, pruvà, poi mette in linea.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"Ambiente","text":"Una copia separata di u sistema per un scopu, cum'è unu per custruisce, unu per pruvà è quellu in linea.","also":["environment","environments","ambienti"],"noTip":1},{"id":"devenv","g":"change","word":"Ambiente di sviluppu","text":"A copia induve travaglia un sviluppatore, spessu nant'à u so urdinatore, induve rompe e cose ùn face male à nimu.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"Ambiente di prova","text":"Una copia separata di u sistema aduprata solu per e prove, cusì u serviziu veru ùn hè micca toccu.","also":["test environment","test environments","ambienti di prova"]},{"id":"staging","g":"change","word":"Ambiente di preparazione (Staging)","text":"Un'ultima copia messa in piedi cum'è quella in linea, per una verifica finale nanzu chì un cambiamentu passi in linea.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"Artefattu di compilazione","text":"U schedariu o u fasciu chì una compilazione pruduce, prontu per esse tenutu, verificatu o messu in linea.","also":["build artifact","build artifacts","artefatti"]},{"id":"hotfix","g":"change","word":"Currezzione d'urgenza (Hotfix)","text":"Una currezzione urgente messa in linea prestu, fora di u pianu nurmale, perchè qualcosa d'impurtante hè rottu.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Un picculu aghjurnamentu chì currege un prublema o chjude un bucu di sicurità. Applicà prestu e patch di sicurità conta.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Numeru di versione","text":"Una etichetta cum'è 2.4.1 chì dice quale versione tù hai. Spessu u primu numeru cambia per i grandi cambiamenti è l'ultimu per e piccule currezzioni.","also":["version number","version numbers","semantic versioning","numeri di versione"]},{"id":"relnotes","g":"change","word":"Note di versione (Release notes)","text":"Una corta lista simplice di ciò chì hà cambiatu in una versione, per e persone chì l'usanu, cumprese e currezzioni è i limiti cunnisciuti. Si dice ancu changelog.","also":["release notes","changelog","change log","note di versione"]},{"id":"flag","g":"change","word":"Interruttore di funzione (Feature flag)","text":"Un interruttore accesu è spentu per una funzione, cusì u travagliu novu pò passà in linea piattatu è esse accesu (o spentu torna) senza una nova versione.","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Currezzione in avanti (Roll forward)","text":"Currege una versione sbagliata mettendu prestu in linea una nova versione curretta invece di tornà à l'antica.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Versione canarinu (Canary)","text":"Mette un cambiamentu in linea prima per un picculu gruppu, è per tutti solu quandu pare bè. Hè chjamatu cusì per i canarini chì i minatori purtavanu sottu terra cum'è avvertimentu.","also":["canary release","canary releases","canary","canarinu"]},{"id":"bluegreen","g":"change","word":"Implementazione blu-verde","text":"Tene duie copie di u sistema in linea è passà a ghjente à a nova d'un colpu, cusì poi tornà subitu à l'antica s'ella va male.","also":["blue-green deployment","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Implementazione senza interruzzione","text":"Mette una nova versione in linea senza chì u serviziu si fermi mai per i so utilizatori.","also":["zero-downtime deployment","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Gestione di i cambiamenti","text":"Aiutà i cambiamenti à riesce : pesà u risicu, ottene l'approvazione ghjusta è sceglie un bonu mumentu. Si dice ancu change management.","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"Cumitatu di cunsigliu per i cambiamenti (CAB)","text":"Un gruppu chì esamina i cambiamenti impurtanti è decide s'elli ponu andà avanti è quandu.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Cambiamentu standard","text":"Un cambiamentu di pocu risicu fattu ogni volta a listessa manera pruvata, dunque approvatu nanzu.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"Cambiamentu nurmale","text":"Un cambiamentu chì deve esse verificatu è approvatu nanzu d'andà avanti.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Cambiamentu d'urgenza","text":"Un cambiamentu chì deve succede subitu per currege o impedisce un prublema seriu, cù una approvazione più rapida in cunseguenza.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatizazione","text":"Fà fà à l'urdinatore un travagliu ripetutu da sè, cusì hè più rapidu è fattu a listessa manera ogni volta.","also":["automation","automated","automatizà"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruttura","text":"E macchine, e reti è i servizii nantu à i quali gira u software.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Infrastruttura cum'è codice (IaC)","text":"Discrive i to servitori è e to impostazioni in schedarii tenuti cù u codice, cusì si ponu rifà esattamente listessi ogni volta.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (nuvola)","text":"Affittà urdinatori, spaziu di memoria è servizii da un grande furnitore per internet, invece d'avè e to propie macchine.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Furnitore di cloud","text":"Una sucietà chì affitta putenza di calculu per internet, cum'è Amazon Web Services (AWS), Microsoft Azure o Google Cloud.","also":["cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Ospitalità web (Hosting)","text":"U locu induve a to app o u to situ web stà è gira perchè a ghjente ci possi ghjunghje, di solitu affittatu à una sucietà.","also":["hosting"]},{"id":"domain","g":"change","word":"Nome di duminiu","text":"L'indirizzu web chì a ghjente scrive, cum'è example.com. Si affitta per annu, dunque deve esse rinnuvatu.","also":["domain name","domain names","domain","duminiu"]},{"id":"dns","g":"change","word":"DNS","text":"Accurtatura di domain name system : u libru d'indirizzi d'internet, chì trasforma un nome cum'è example.com in l'indirizzu di l'urdinatore ghjustu.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Un pacchettu sigillatu chì tene una app è tuttu ciò chì li serve, cusì gira listessu nant'à ogni urdinatore. Docker hè l'arnese u più cunnisciutu.","also":["containers","Docker","cuntinitore"],"noTip":1},{"id":"vm","g":"change","word":"Macchina virtuale (VM)","text":"Un urdinatore fintu chì gira drentu à unu veru, cusì una grande macchina pò fà cum'è parechje.","also":["VM","VMs","virtual machines","virtual machine"]},{"id":"serverless","g":"change","word":"Serverless (senza servitore)","text":"Fà girà codice senza avè à curà nisun servitore : u furnitore u face girà quandu ci vole è tù paghi ciò chì usi."},{"id":"lb","g":"change","word":"Ripartitore di carica (Load balancer)","text":"Qualcosa chì sparte i visitatori nantu à parechji servitori, cusì nisunu ùn hè sopraffattu.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Un magazinu praticu di i risultati recenti tenuti vicinu, per ùn avè à ripiglià li nè à calculà li torna. Svuttà lu pò currege e pagine chì parenu sorpassate.","also":["caches","caching","cached","memoria rapida"]},{"id":"cdn","g":"change","word":"Rete di distribuzione di cuntenutu (CDN)","text":"Un inseme mundiale di servitori chì tenenu copie di e to pagine è imagine vicinu à i to visitatori, cusì si carichenu prestu.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrazione","text":"Spustà dati o sistemi da una vechja struttura à una nova, o cambià cun cura cumu hè disposta una basa di dati.","also":["migration","migrations","database migration","migrazioni"]},{"id":"service","g":"run","word":"Serviziu","text":"Qualcosa chì tù hai custruitu è chì a ghjente ci conta, cum'è un situ web o un'appiecazione, curatu perchè cuntinueghji à funziunà. Marca “Stu prughjettu hè un serviziu” è dì ciò ch'ellu offre, quale l'adopra è quale hè di guardia.","also":["servizii","service"]},{"id":"uptimepct","g":"run","word":"Tempu attivu (Uptime)","text":"Quantu tempu un serviziu funziona, di solitu in percentuale. 99,9 % permette sempre circa 43 minuti fora di serviziu à u mese.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Cuntrollu di funziunamentu","text":"Un cuntrollu autumaticu, ogni pochi minuti, chì u to serviziu risponde sempre. S'ellu falla parechje volte di fila, AI-gile apre da per ellu una carta d'incidente.","also":["uptime checks","verifiche di tempu attivu"]},{"id":"statuspage","g":"run","word":"Pagina di statu","text":"Una pagina publica chì mostra s'è un serviziu funziona (verde, aranciu o rossu) cù l'ultima nutizia, cusì a ghjente chì l'adopra pò verificà invece di dumandà.","also":["pagine di statu","status page"]},{"id":"desk","g":"run","word":"Serviziu d'assistenza","text":"Induve arrivanu e dumande è e segnalazioni di a ghjente chì adopra u to serviziu. AI-gile classa ognuna cum'è richiesta, incidente o idea, è ti a dice quandu pare qualcosa digià segnalatu.","also":["servizii d'assistenza","assistenza","helpdesk"]},{"id":"svcrequest","g":"run","word":"Richiesta di serviziu","text":"Qualchissia chì dumanda qualcosa di currente, cum'è un contu novu o un pocu d'aiutu, piuttostu chè di segnalà chì qualcosa hè rottu. Aspetta u so turnu; un incidente passa prima.","also":["richieste di serviziu"]},{"id":"incident","g":"run","word":"Incidente","text":"Qualcosa di rottu o chì ùn funziona micca bè per e persone chì l'usanu avà, cum'è u situ web fora di serviziu o assai lentu. Una carta d'incidente 🔥 passa davanti à a fila : rimette la in funzione vene prima.","also":["incidenti","incident"]},{"id":"major","g":"run","word":"Incidente maiore","text":"Un incidente grossu: assai ghjente tocca, o soldi o dati in periculu. Un buttone mette tutte e squadre nantu (sciame), sveglia quellu chì hè di guardia è dumanda un aghjurnamentu di statu ogni 30 minuti.","also":["incidenti maiori","major incident"]},{"id":"oncall","g":"run","word":"Di guardia","text":"Esse quellu chì risponde quandu qualcosa si rompe, ancu di notte. Ogni serviziu hà un membru di a squadra di guardia, svegliatu u primu per i so incidenti.","also":["guardia","on call","on-call"]},{"id":"replyby","g":"run","word":"Ora di risposta","text":"Quantu tempu una carta pò aspettà una prima risposta, per esempiu un'ora per un incidente. Dopu piglia un orologliu rossu, cusì nunda ùn hè scurdatu in silenziu. Si chjama ancu scopu di risposta.","also":["ore di risposta","scopu di risposta","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un sguardu cortu in daretu dopu un incidente: ciò chì hè accadutu, ciò chì hà aiutatu è ciò chì ci vole à cambià, senza incolpà à nimu. Un incidente ùn pò esse chjosu senza unu.","also":["postmortem","revisione dopu l'incidente"]},{"id":"problem","g":"run","word":"Prublema","text":"A causa piatta daretu à unu o parechji incidenti. Una carta 🧩 prublema raggruppa l'incidenti chì tornanu sempre, cusì a causa hè trovata è currigiuta per sempre.","also":["prublemi","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa radica","text":"A vera ragione per chì qualcosa s'hè rottu, è micca solu ciò chì tù hai vistu andà male. Curreghji a causa radica è l'incidente ùn torna più.","also":["cause radiche","root cause"]},{"id":"workaround","g":"run","word":"Suluzione pruvisoria","text":"Un modu di mantene e cose in funziunamentu finchè a vera currezzione sia pronta, cum'è rilancià qualcosa quandu si blocca. Hè scritta nant'à a carta di u prublema cusì nimu ùn hà da truvalla torna.","also":["suluzioni pruvisorie","workaround"]},{"id":"knownerror","g":"run","word":"Errore cunnisciutu","text":"Un prublema chì a so causa hè capita ma ùn hè ancu currettu, di solitu cù una suluzione di ripiegu scritta. 🧩 Errori cunnisciuti ne face a lista, cusì ognunu usa a suluzione invece di scavà torna.","also":["errori cunnisciuti","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Istruzzioni passu à passu per currege un tipu di guai cunnisciutu, cusì hè fattu di listessa manera, prestu, ogni volta. Dopu un incidente maiore a squadra ne pò prupone unu per chì tù l'appruvi.","also":["runbooks","manuale d'operazione"]},{"id":"ci","g":"run","word":"Elementu di cunfigurazione","text":"Una cosa da quale u to serviziu dipende, cum'è un servitore, un duminiu, un certificatu, una chjave o un furnitore. 🗂️ Elementi di cunfigurazione i elenca per serviziu, cusì vedi ciò chì un incidente tocca è ciò chì ci vole à rinnovà o à salvà.","also":["elementi di cunfigurazione"]},{"id":"expiry","g":"run","word":"Data di scadenza","text":"A data dopu à a quale qualcosa ferma di funziunà s'ellu ùn hè rinnuvatu, cum'è u certificatu di sicurità d'un situ web o u so indirizzu web. AI-gile veglia nant'à ste date è face una carta per rinnuvà ognuna 30 ghjorni nanzu, cusì nunda ùn si ferma per sorpresa.","also":["date di scadenza","scadenza","sorveglianza di e scadenze"]},{"id":"backup","g":"run","word":"Copia di salvezza","text":"Una copia salvata di i to dati di prima, per ricorre ci s'è qualcosa hè persu o guastu. AI-gile face ogni ghjornu una copia di salvezza di i to tavulini.","also":["copie di salvezza","backup"]},{"id":"restore","g":"run","word":"Risturà","text":"Rimette i dati da una copia di salvezza. Una copia di salvezza conta daveru solu quandu sai ch'ella pò esse risturata, allora vale a pena di pruvà da tantu in tantu.","also":["risturazione","risturatu","restore"]},{"id":"svcreview","g":"run","word":"Revisione di serviziu","text":"Un sguardu in daretu nant'à un mese di un serviziu: incidenti aperti è riparati, quantu prestu a ghjente hà avutu una risposta, funziunamentu è token aduprati. A Revisione mensile a mostra per ogni serviziu.","also":["revisioni di serviziu","revisione mensile","revisioni mensili"]},{"id":"accessreview","g":"run","word":"Revisione d'accessu","text":"Verificà ogni 90 ghjorni quale pò sempre entre : ligami spartuti, roli di l'amichi è parolle d'ordine è chjavi salvate. Per ognunu, sceglii di tene lu o di caccià lu, cusì l'accessi vechji ùn restanu micca.","also":["revisioni d'accessu"]},{"id":"improvements","g":"run","word":"Lista di i miglioramenti","text":"Tuttu ciò chì a squadra hà decisu di fà megliu, in un locu solu: suggerimenti di a retro, azzioni di e revisioni è currezzioni di i prublemi, ognunu cù u so statu. A trovi sottu 📈 Miglioramenti.","also":["liste di i miglioramenti","miglioramenti"]},{"id":"tokencap","g":"run","word":"Tettu di token","text":"Un limitu mensile di i token chì l'agenti di un serviziu ponu aduprà. À 80% ricevi un avertimentu; à 100% u so travagliu in fondu aspetta u mese dopu o finchè tù ùn alzi u tettu.","also":["tetti di token"]},{"id":"svcmgmt","g":"run","word":"Gestione di i servizii","text":"Tuttu ciò chì ci vole per tene un serviziu utile è in funzione per e persone chì ne dipendenu, ghjornu dopu ghjornu.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Una guida assai usata per a bona gestione di i servizii, chì cuntene cose cum'è incidenti, prublemi è cambiamenti. U nome vulia dì una volta IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Gestione di i servizii IT (ITSM)","text":"Gestisce a tecnulugia cum'è un serviziu per e persone, cù modi chjari di trattà e dumande, l'incidenti, i cambiamenti è i migliuramenti.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Serviziu gestitu","text":"Un serviziu chì qualchissia altru face girà è cura per tè, sottu à un accordu nant'à cumu deve funziunà.","also":["managed service","managed services","servizii gestiti"]},{"id":"svcowner","g":"run","word":"Pruprietariu di u serviziu","text":"A persona chì risponde d'un serviziu in tuttu : cumu funziona, ciò ch'ellu costa è cumu migliora.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"Accordu di livellu di serviziu (SLA)","text":"Una prumessa scritta à i clienti nant'à cumu funziunerà un serviziu, cum'è « attivu 99,9 % di u tempu » o « risposta in menu d'una ora », spessu cù rimborsu s'ella ùn hè micca rispettata.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Scopu di livellu di serviziu (SLO)","text":"U scopu propiu di a squadra per cumu deve funziunà un serviziu nantu à un periudu, di solitu fissatu un pocu più strettu chè l'SLA per prudenza.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Indicatore di livellu di serviziu (SLI)","text":"A misura vera chì tù cuntrolli à pettu à un scopu, cum'è a parte di e visite chì si sò caricate bè.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Dispunibilità","text":"S'è e persone ponu usà un serviziu quandu ne anu bisognu, spessu misuratu cum'è tempu attivu.","also":["availability","high availability","alta dispunibilità"]},{"id":"downtime","g":"run","word":"Tempu fora di serviziu (Downtime)","text":"U tempu quandu un serviziu ùn funziona micca o hè spentu, pianificatu o micca.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Bilanciu d'errori (Error budget)","text":"A piccula quantità di fallimentu chì u to scopu d'affidabilità permette. Finu à chì ne firma, poi piglià risichi cù i cambiamenti ; una volta cunsumatu, rallenti.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Panna (Outage)","text":"Un mumentu induve un serviziu hè fermu o assai rottu per i so utilizatori.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Degradatu","text":"Funziona, ma male : lentu, o cù qualchì parte chì ùn funziona micca.","also":["degraded","degraded service","serviziu degradatu"]},{"id":"monitoring","g":"run","word":"Surveglianza (Monitoring)","text":"Guardà un serviziu automaticamente tuttu u tempu, cusì i prublemi sò visti, idealmente nanzu chì l'utilizatori se n'avvedinu.","also":["monitoring","monitorà"]},{"id":"observability","g":"run","word":"Osservabilità","text":"Quantu si pò sapè ciò chì succede drentu à un sistema da fora, cù i so ghjurnali, numeri è tracce.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Ghjurnale (Log)","text":"Un ghjurnale chì un prugramma tene di ciò ch'ellu face, adupratu per capisce ciò chì hè andatu male.","also":["log","logs","logging","ghjurnali"],"noTip":1},{"id":"trace","g":"run","word":"Traccia (Trace)","text":"Una nota di cumu una dumanda viaghja per e diverse parti d'un sistema, passu per passu, chì mostra induve hà rallentatu.","also":["trace","traces","tracing","tracce"]},{"id":"latency","g":"run","word":"Latenza","text":"Quantu tempu ci mette qualcosa à risponde, cum'è l'attesa trà u clic è a pagina chì compare.","also":["latency"]},{"id":"alert","g":"run","word":"Allerta","text":"Un messaghju automaticu chì dice chì qualcosa hà bisognu d'attenzione, cum'è u situ web chì ùn risponde micca.","also":["alert","alerts","alerting","allerte"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Stanchezza d'allerte","text":"Quandu ci sò tante allerte chì a ghjente cumincia à ignurà le, ancu quelle impurtante.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Pannellu di cuntrollu (Dashboard)","text":"Una schermata chì mostra i numeri è i stati più impurtanti d'un sguardu.","also":["dashboard","dashboards","tavula di bordu"],"noTip":1},{"id":"paging","g":"run","word":"Chjamata d'urgenza (Paging)","text":"Chjamà o sveglià d'urgenza a persona di guardia per un prublema.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Escalazione","text":"Chjamà qualchissia cù più cumpetenza o autorità quandu un prublema ùn pò esse risoltu à u livellu attuale, o micca abbastanza prestu.","also":["escalation","escalate","escalated","escalà"]},{"id":"triage","g":"run","word":"Triage","text":"Classà prestu i prublemi chì ghjunghjenu secondu quantu sò urgenti è impurtanti, cusì u peghju hè trattatu prima.","also":["triaged"]},{"id":"impact","g":"run","word":"Impattu","text":"Quantu qualcosa tocca e persone : quante, è quantu male.","noTip":1},{"id":"urgency","g":"run","word":"Urgenza","text":"Quantu prestu qualcosa deve esse trattatu. Impattu è urgenza inseme fissanu a priurità.","noTip":1},{"id":"plevels","g":"run","word":"Livelli di priurità (P1, P2…)","text":"Etichette per quantu hè urgente un prublema. P1 hè u più seriu è vole azzione subitu.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Fila di ticket","text":"A lista di e dumande è di l'incidenti chì aspettanu d'esse pigliati.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Prima linea è seconda linea","text":"Livelli di sustegnu : a prima linea piglia a chjamata è currege e cose simplici ; a seconda linea hà cumpetenze più prufonde per e cose più cumplicate. Si dice ancu livellu 1 è livellu 2.","also":["first-line support","tier 1","tier 2","prima linea","seconda linea"]},{"id":"ic","g":"run","word":"Capu d'incidente","text":"L'unica persona chì guida a risposta à un incidente, cusì ognunu sà quale decide è quale face chì.","also":["incident commander","incident commanders","cumandante d'incidente"]},{"id":"responsetime","g":"run","word":"Tempu di risposta","text":"Quantu tempu ci vole nanzu chì qualchissia pigli per a prima volta una dumanda o un incidente.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Tempu di risuluzione","text":"Quantu tempu ci vole per risolve cumpletamente una dumanda o un incidente, da u raportu à a currezzione.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Tempu mediu di ripresa (MTTR)","text":"In media, quantu tempu ci vole per rimette un serviziu in funzione dopu ch'ellu s'hè rottu. MTTR pò vulè dì cose un pocu sfarenti, dunque dì ciò chì tù misuri.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Tempu mediu trà i fallimenti (MTBF)","text":"In media, quantu tempu un serviziu gira nanzu chì qualcosa si rompi.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Basa di dati di cunfigurazione (CMDB)","text":"A lista di tutti i to elementi di cunfigurazione è di cumu sò cunnessi, cusì poi vede ciò chì dipende da chì.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Risorsa (Asset)","text":"Tuttu ciò chì hà valore è chì tù pussedi o paghi per fà girà u serviziu, cum'è un urdinatore purtatile, una licenza di software o un duminiu.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Pianificazione di a capacità","text":"Assicurassi chì ci serà abbastanza putenza d'urdinatore, spaziu di memoria è persone per ciò chì vene.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Scalabilità (Scaling)","text":"Fà fronte à più utilizatori dendu più putenza à una macchina (scalà in altu) o aghjunghjendu più macchine (scalà in largu).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Cuntinuità d'attività","text":"Piani per tene in marcia l'impurtante quandu qualcosa di grande va male, cum'è perde un uffiziu, un furnitore chjave o l'urdinatori.","also":["business continuity","business continuity plan","pianu di cuntinuità"]},{"id":"dr","g":"run","word":"Ripresa dopu un disastru (DR)","text":"U pianu è l'arnesi per rimette in funzione un serviziu dopu qualcosa di seriu, cum'è perde un centru di dati sanu.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Tempu massimu di ripresa (RTO)","text":"U tempu u più longu chì un serviziu pò esse fermu dopu un disastru, nanzu di duvè funziunà torna.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Perdita massima di dati (RPO)","text":"Quantu dati recenti ti poi permette di perde, misurati in tempu. Un RPO d'una ora vole dì copie di salvezza almenu ogni ora.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Ridondanza","text":"Avè pezzi di ricambiu pronti, cum'è un secondu servitore, cusì un fallimentu solu ùn ferma micca u serviziu.","also":["redundancy","ridondante"]},{"id":"failover","g":"run","word":"Cambiu automaticu (Failover)","text":"Passà da sè à un sistema di ricambiu quandu quellu abituale falla.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"Puntu unicu di fallimentu","text":"Un solu pezzu chì porta tuttu cun ellu quand'ellu si rompe, perchè ùn ci hè ricambiu.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Finestra di manutenzione","text":"Un mumentu pianificatu induve un serviziu pò esse fermu o lentu per a manutenzione, annunziatu nanzu à l'utilizatori.","also":["maintenance window","maintenance windows","planned maintenance","manutenzione pianificata"]},{"id":"handover","g":"run","word":"Passaghju di testimone (Handover)","text":"Passà u travagliu, e cunniscenze è a risponsabilità à un'altra persona o squadra, cusì nunda ùn si perde.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Basa di cunniscenze","text":"Una cullezzione d'articuli d'aiutu è di risposte, per l'utilizatori è per a squadra.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Suddisfazione di i clienti (CSAT)","text":"Una nota data da l'utilizatori chì dice quantu eranu cuntenti, spessu dumandata dopu a chjusura d'una dumanda.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Furnitore","text":"Una sucietà esterna da a quale tù dipendi, cum'è u to furnitore d'ospitalità web. Si dice ancu vendor o terza parte.","also":["supplier","suppliers","vendor","vendors","third party","furnitori","terza parte"],"noTip":1},{"id":"retire","g":"run","word":"Chjusura d'un serviziu","text":"Spegne un serviziu per sempre, in sicurità : avvisà i so utilizatori, trattà i so dati è accessi, è piantà i so costi.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Fine di vita (EOL)","text":"Quandu un pruduttu ùn riceve più aghjurnamenti o sustegnu da u so fabbricatore, dunque deve esse rimpiazzatu.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Cibersicurità","text":"Prutege i sistemi è i dati da l'intrusione, u furtu o i danni.","also":["cybersecurity","cyber security","sicurità informatica"]},{"id":"authn","g":"sec","word":"Autentificazione","text":"Verificà quale hè qualchissia, di solitu cù una parolla d'ordine o un codice. Spessu abbreviatu authn.","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"Autorizazione","text":"Verificà ciò chì qualchissia pò fà una volta chì si sà quale hè. Spessu abbreviatu authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Autentificazione à più fattori (MFA)","text":"Cunnettesi cù duie o più pruve, cum'è una parolla d'ordine più un codice nant'à u to telefuninu. Si dice ancu à dui fattori (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","multi-factor authentication"]},{"id":"sso","g":"sec","word":"Cunnessione unica (SSO)","text":"Cunnettesi una volta per entre in parechji sistemi, cum'è usà u to contu di travagliu dapertuttu.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Gestore di parolle d'ordine","text":"Una app chì crea parolle d'ordine forti è si ne ricorda per tè.","also":["password manager","password managers"]},{"id":"secret","g":"sec","word":"Sicretu (Secret)","text":"Una parolla d'ordine, chjave o altru codice privatu chì un prugramma usa per entre in qualcosa. Ùn deve mai esse spartu nè scrittu in u codice.","also":["secret","secrets","sicreti"],"noTip":1},{"id":"apikey","g":"sec","word":"Chjave API","text":"Un codice sicretu chì lascia un prugramma usà l'API d'un altru serviziu, è mostra quale l'usa (è u paga).","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token d'accessu","text":"Un lasciapassà tempurariu chì pruva chì un prugramma hà u dirittu d'entre, cusì ùn hà micca bisognu di a to parolla d'ordine ogni volta. Ùn hè micca listessu chè un token IA.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"Cifratura","text":"Imbruglià l'infurmazioni perchè solu qualchissia cù a chjave ghjusta e possi leghje.","also":["encryption","encrypted","encrypt","cifrà"]},{"id":"https","g":"sec","word":"HTTPS","text":"A manera sicura chì e pagine web viaghjanu, mostrata da u lucchettu in u to navigatore, cusì nimu à mezu ùn pò leghje le nè cambià le."},{"id":"cert","g":"sec","word":"Certificatu SSL/TLS","text":"Una carta d'identità digitale chì lascia un situ web pruvà quale hè è usà HTTPS. Scade, dunque deve esse rinnuvata.","also":["SSL/TLS certificate","TLS certificate","SSL certificate","certificate","certificates","certificatu"]},{"id":"permissions","g":"sec","word":"Permessi","text":"E regule di quale pò vede o cambià chì.","also":["permissions","permission","permessu"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Dirittu minimu","text":"Dà à ogni persona o prugramma solu l'accessu di chì hà veramente bisognu, è solu per u tempu chì li serve.","also":["least privilege","principle of least privilege","principiu di u dirittu minimu"]},{"id":"rbac","g":"sec","word":"Cuntrollu d'accessu per rolu (RBAC)","text":"Dà l'accessu per rolu, cum'è lettore o redattore, invece di persona per persona.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Vulnerabilità","text":"Una debulezza chì qualchissia puderia usà per entre di forza o fà male.","also":["vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Una debulezza chì l'attaccanti cunnoscenu nanzu chì i fabbricatori aghjanu avutu tempu di currege la.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software dannosu, cum'è i virus, fattu per dannighjà, spià o arrubà.","also":["prugramma malignu"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware chì blocca i to schedarii è dumanda soldi per sbluccà li. E bone copie di salvezza sò a megliu difesa.","also":["ransomware attack","attaccu ransomware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Messaghji falsi chì pruvanu à ingannà ti per fà ti dà parolle d'ordine o soldi, o per fà ti apre qualcosa di dannosu.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Ingegneria suciale","text":"Ingannà e persone, invece di l'urdinatori, per ottene l'accessu, cum'è una falsa chjamata di u « sustegnu IT »."},{"id":"firewall","g":"sec","word":"Muru di focu (Firewall)","text":"Una guardia chì decide chì trafficu di rete pò entre o esce.","also":["firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Accurtatura di virtual private network : un ligame privatu è cifratu per internet, spessu adupratu per ghjunghje à i sistemi di u travagliu in sicurità.","also":["virtual private network","rete privata virtuale"]},{"id":"ddos","g":"sec","word":"Negazione di serviziu (DoS, DDoS)","text":"Innundà un serviziu cù tantu trafficu falsu chì e persone vere ùn ponu più usà lu. DDoS vole dì chì vene da parechji urdinatori à tempu.","also":["DoS","DDoS","denial of service","DDoS attack","attaccu DDoS"]},{"id":"pentest","g":"sec","word":"Prova d'intrusione (pen test)","text":"Ingaghjà esperti amichevuli chì pruvanu à entre di forza, cusì e debulezze sò truvate nanzu chì l'attaccanti veri e truvinu.","also":["pen test","pen testing","penetration testing","pentest","penetration test"]},{"id":"audit","g":"sec","word":"Auditu di sicurità","text":"Una verifica attenta di quantu qualcosa hè prutettu, paragunata à una lista di bone pratiche.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Mudellazione di e minacce","text":"Pensà à quale puderia attaccà qualcosa, cumu, è ciò chì si pò fà per impedì lu.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Fuga di dati","text":"Quandu l'infurmazioni private ghjunghjenu à persone chì ùn duverianu micca avè le, o sò perse o cambiate senza permessu.","also":["data breach","data breaches","violazione di dati"]},{"id":"pii","g":"sec","word":"Dati persunali","text":"Ogni infurmazione nant'à una persona chì si pò ricunnosce, cum'è un nome, un indirizzu email o un locu. Si dice ancu PII.","also":["PII","personally identifiable information","personal data"]},{"id":"gdpr","g":"sec","word":"GDPR (RGPD)","text":"A lege europea nant'à i dati persunali (u Regnu Unitu hà a so propria versione) : cullettà solu ciò chì ci vole, tene lu in sicurità, è lascià e persone vede o sguassà i soi.","also":["General Data Protection Regulation","RGPD"]},{"id":"dataprot","g":"sec","word":"Prutezzione di i dati","text":"Curà bè i dati persunali è in u rispettu di a lege.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Pulitica di vita privata","text":"Una pagina publica chì dice quali dati persunali tù culletti, perchè, è ciò chì tù ne faci.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Cunsensu","text":"U sì chjaru è liberu d'una persona à chì i so dati sianu usati in una manera precisa. Pò ripiglià lu in ogni mumentu.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Un picculu schedariu chì un situ web salva in u to navigatore per ricurdassi di e cose, cum'è u fattu d'esse cunnessu. Certi anu bisognu prima di u to cunsensu.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizazione di i dati","text":"Cullettà è tene solu i dati persunali chì ci vulenu veramente per u travagliu.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Cunservazione di i dati","text":"Per quantu tempu i dati sò tenuti nanzu d'esse sguassati. Ùn tene li più di u bisognu hè più sicuru è spessu a lege.","also":["data retention","retention period","durata di cunservazione"]},{"id":"anon","g":"sec","word":"Anunimizazione","text":"Cambià i dati di manera chì ùn si possi più, ragiunevulmente, identificà nimu.","also":["anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonimizazione","text":"Scambià nomi è altri dettagli per codici, cù una chjave tenuta à parte per ricunnette li. Sò sempre dati persunali.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Cuntrattu di trattamentu di i dati (DPA)","text":"Un cuntrattu chì dice cumu un furnitore pò trattà i dati persunali in u to nome.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Valutazione d'impattu nant'à a prutezzione di i dati (DPIA)","text":"Un sguardu attentu, nanzu di principià, à cumu un pianu per usà dati persunali pò toccà e persone è cumu calà i risichi.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Ghjurnale d'auditu","text":"Una nota di quale hà fattu chì è quandu, cusì l'azzioni ponu esse verificate dopu.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Cunfurmità","text":"Seguità e lege, e regule è i standard chì ti cuncernanu, è pudè mostrà chì tù i rispetti.","also":["compliance","compliant","cunforme"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Un standard internaziunale cunnisciutu per gestisce a sicurità di l'infurmazioni. E sucietà ponu esse certificate secondu questu.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Un raportu americanu, verificatu da auditori esterni, chì mostra chì una sucietà cura bè i dati di i clienti.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Una IA chì travaglia nant'à un cumpitu da sè : leghje u codice, face cambiamenti, eseguisce verifiche è rende contu. U so travagliu hè sempre verificatu.","also":["agenti"]},{"id":"token","g":"ai","word":"Token","text":"I picculi pezzi di testu chì una IA leghje è scrive, circa trè quarti di una parolla ognunu. L'usu di a IA hè cuntatu in token, dunque menu token lascianu più di u to pianu.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Una piccula cumanda chì gira da sè à un mumentu fissu, per esempiu quandu una sessione IA principia, cusì a squadra sente i to cummenti.","also":["hooks"]},{"id":"ai","g":"ai","word":"Intelligenza artificiale (IA)","text":"Sistemi d'urdinatore chì facenu cose chì, di solitu, pensemu ch'elle anu bisognu d'una persona, cum'è scrive, risponde à dumande o ricunnosce imagine.","also":["IA","AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Apprendimentu automaticu (ML)","text":"Una manera di fà amparà à l'urdinatori mudelli da assai esempii, invece di dà li regule esatte.","also":["ML","machine learning","apprendimentu di a macchina"]},{"id":"model","g":"ai","word":"Mudellu","text":"U « cerbellu » furmatu d'un sistema IA, custruitu amparendu da numeri enormi d'esempii. I mudelli sò sfarenti in capacità, prestezza è prezzu.","also":["mudelli","model","models","AI model","mudellu IA"],"noTip":1},{"id":"llm","g":"ai","word":"Grande mudellu di lingua (LLM)","text":"Un mudellu IA furmatu nant'à quantità immense di testu, cusì pò leghje è scrive a lingua.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"IA generativa","text":"IA chì crea cose novi, cum'è testu, imagine o codice, invece di solu classà le o ricunnosce le.","also":["Generative AI","GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Un prugramma cù u quale tù parli in lingua di tutti i ghjorni, scrivendu o parlendu.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ciò chì tù dai à una IA : a to dumanda o e to istruzzioni, più tuttu ciò chì li passi. I prompt più chjari danu di solitu risposte migliori.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Ingegneria di i prompt","text":"L'arte di scrive prompt chì danu risultati affidabili è utili.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Prompt di sistema","text":"Istruzzioni di fondu chì una IA riceve nanzu chì a cunversazione cumincii, chì fissanu u so rolu è e so regule. Pesanu più chè ciò chì tù scrivi.","also":["system prompt","system prompts","system instruction","system instructions","istruzzioni di sistema"]},{"id":"context","g":"ai","word":"Cuntestu","text":"Tuttu ciò chì a IA pò vede mentre travaglia : l'istruzzioni, i to messaghji, i schedarii ch'ella hà lettu è e risposte di nanzu.","noTip":1},{"id":"ctxwin","g":"ai","word":"Finestra di cuntestu","text":"Quantu una IA pò tene à mente à tempu, misuratu in token. Passatu stu limite, e parti più vechje sò lasciate cascà o riassunte.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Sessione","text":"Una cunversazione di travagliu cù una IA, da u principiu à a fine. Una sessione nova principia cù una memoria fresca.","also":["session","sessions","sessioni"],"noTip":1},{"id":"memory","g":"ai","word":"Memoria","text":"Note chì una IA tene da una sessione à l'altra, cusì si ricorda di e to preferenze è di e decisioni passate.","noTip":1},{"id":"hallucination","g":"ai","word":"Allucinazione","text":"Quandu una IA dice qualcosa cun aria sicura, ma chì hè inventatu o sbagliatu. Verifica i fatti impurtanti.","also":["hallucination","hallucinations","hallucinate","hallucinates","allucinazioni"]},{"id":"training","g":"ai","word":"Furmazione (Training)","text":"Insegnà à un mudellu mostrendu li numeri enormi d'esempii, nanzu chì qualchissia l'usi.","also":["training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Dati di furmazione","text":"L'esempii da i quali un mudellu hà amparatu. A so cunniscenza si ferma à a data induve quelli dati sò stati cullettati.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Limite di cunniscenza","text":"A data induve finisce a cunniscenza integrata d'una IA. Ùn sà micca e cose di dopu, salvu s'ella e cerca.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Affinamentu (Fine-tuning)","text":"Furmazione supplementare d'un mudellu esistente nant'à i to propii esempii, per fà lu megliu in un travagliu particulare.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferenza","text":"Un mudellu IA chì hè veramente adupratu per risponde à qualcosa, à u cuntrariu d'esse furmatu.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Usu d'arnesi (Tool use)","text":"Una IA chì pò fà cose, micca solu parlà : eseguisce cumande, leghje schedarii o cercà nantu à u web, cù l'arnesi chì l'app li dà.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Sub-agente","text":"Una IA aiutante à a quale una IA principale dà un travagliu più chjucu, è da a quale riceve u risultatu.","also":["subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agente","text":"Parechje IA chì travaglianu inseme nant'à un travagliu, ognuna cù a so parte, cum'è una piccula squadra.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonumia","text":"Quantu una IA pò fà da sè nanzu di duvè dumandà à una persona.","also":["autonomy","autonomous","autonomu"]},{"id":"hitl","g":"ai","word":"Umanu in u circuitu (Human in the loop)","text":"Tene una persona implicata per verificà o appruvà ciò chì face a IA à i mumenti chjave. In AI-gile sì tù.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Parapetti (Guardrails)","text":"Limiti è verifiche chì tenenu sicure l'azzioni d'una IA, cum'è esige una approvazione nanzu chì qualcosa passi in linea. Calanu u risicu d'errori, ma ùn l'escludenu micca.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Generazione aumentata da ricerca (RAG)","text":"Lascià una IA cercà cose in i to propii ducumenti nanzu di risponde, cusì e so risposte si basanu nantu à i to fatti.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Incrustazione (Embedding)","text":"Trasfurmà un testu in una lista di numeri chì ne piglia u significatu, cusì un urdinatore pò truvà cose chì volenu dì a listessa cosa.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Basa di dati vettoriale","text":"Una basa di dati fatta per cercà in quelle liste di numeri (incrustazioni), per truvà materiale di significatu simile.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Protocollu di cuntestu di mudellu (MCP)","text":"Una manera cumuna di cunnette arnesi è fonti di dati à l'app IA, cusì una IA pò usà li.","also":["MCP","Model Context Protocol"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Una impostazione per quantu audaci sò e risposte d'una IA. Bassa dà risposte più stabili è prevedibili ; alta ne dà di più varie. Nè l'una nè l'altra a face sempre ghjusta.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodale","text":"Capace di travaglià cù più d'un tipu d'infurmazione, cum'è testu, imagine è sonu.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Valutazione (eval)","text":"Una prova pianificata di quantu bè una IA riesce nant'à esempii scelti, per pudè paragunà mudelli o prompt.","also":["eval","evals","evaluation"]},{"id":"bias","g":"ai","word":"Pregiudiziu (Bias)","text":"Quandu una IA (o una persona) pende ingiustamente da un latu, spessu per via di ciò ch'ella hà amparatu.","also":["bias","biased","pregiudizii"],"noTip":1},{"id":"responsible","g":"ai","word":"IA rispunsevule","text":"Usà a IA in modu ghjustu, sicuru è onestu, cù e persone sempre rispunsevuli di i risultati.","also":["responsible AI","ethical AI","IA etica"]},{"id":"injection","g":"ai","word":"Iniezione di prompt","text":"Un tranellu induve istruzzioni piattate in una pagina web o un schedariu pruvanu à fà fà à una IA qualcosa chì u so utilizatore ùn avia micca dumandatu.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limite di frequenza","text":"Un tettu per quante dumande tù poi mandà à un serviziu in un tempu fissu. S'è tù u passi, ti tocca à aspettà.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limite d'usu","text":"Quantu travagliu IA permette u to pianu in un periudu, dopu à u quale si ferma o costa di più.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Custruisce software soprattuttu discrivendu ciò chì tù voli à una IA è lasciendu la scrive u codice.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"A somma di soldi messa da parte per qualcosa.","also":["budgets","bilanciu"],"noTip":1},{"id":"costest","g":"money","word":"Stima di u costu","text":"Una prima stima di ciò chì qualcosa custerà, nanzu di principià.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Ritornu nant'à l'investimentu (ROI)","text":"Ciò chì ti torna paragunatu à ciò chì tù hai messu. S'ellu hè pusitivu, ne valia a pena.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Costu tutale di pruprietà (TCO)","text":"Tuttu ciò chì qualcosa costa veramente in tutta a so vita, micca solu u prezzu d'acquistu : funziunamentu, sustegnu, aghjurnamenti è infine a so chjusura.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx è OpEx","text":"CapEx sò i soldi spesi in anticipu per cose chì tù teni ; OpEx sò e spese cuntinue, cum'è e fatture di ogni mese.","also":["CapEx","OpEx","capital expenditure","operating expenditure","CapEx and OpEx"]},{"id":"subscription","g":"money","word":"Abbunamentu","text":"Pagà regularmente, di solitu à u mese o à l'annu, per cuntinuà à usà qualcosa.","also":["subscription","subscriptions","abbunamenti"],"noTip":1},{"id":"saas","g":"money","word":"Software cum'è serviziu (SaaS)","text":"Software chì tù usi in linea è paghi per abbunamentu, mentre chì u fabbricatore u face girà per tè.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Pagà ciò chì s'usa","text":"Pagà solu ciò chì tù usi, cum'è u calculu in cloud o i token IA.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Supplementu d'usu (Overage)","text":"Usu al di là di ciò chì u to pianu include, chì pò costà di più.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Allerta di fatturazione","text":"Un messaghju quandu a spesa o l'usu ghjunghje à un livellu chì tù hai sceltu. T'avvisa, ma ùn ferma micca sempre i costi supplementari.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Livellu gratuitu","text":"Un livellu gratuitu d'un serviziu pagante, cù limiti. Praticu per principià.","also":["free tier","free plan","pianu gratuitu"]},{"id":"pricing","g":"money","word":"Pianu di prezzi","text":"I diversi pacchetti chì un serviziu vende, ognunu cù u so prezzu è i so limiti.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licenza","text":"E regule di cumu tù poi usà, copià, cambià o sparte qualcosa fattu da qualchissia altru, cum'è software, caratteri o imagine.","also":["licence","licences","license","licenses","licenze"],"noTip":1},{"id":"opensource","g":"money","word":"Fonte aperta (Open source)","text":"Software di u quale ognunu pò leghje, usà è spessu cambià u codice gratuitamente, secondu e regule di a so licenza.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licenza open source","text":"E regule chì venenu cù u codice open source. Certe ti lascianu fà guasi tuttu (cum'è MIT) ; altre ti dumandanu di sparte ancu i to cambiamenti (cum'è GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Pruprietariu (Proprietary)","text":"Appartene à una sucietà è ùn hè micca liberu di copià o di cambià. L'uppostu di l'open source.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Dirittu d'autore","text":"U dirittu legale d'un creatore di cuntrullà e copie di a so opera, cumprese u codice è i testi.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Pruprietà intellettuale (IP)","text":"Idee è creazioni chì a lege tratta cum'è pussedute, cum'è codice, disegni, nomi è logò.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Cundizioni d'usu","text":"E regule chì tù accetti quandu usi un serviziu.","also":["terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Cuntrattu","text":"Un accordu scrittu trà duie parti chì a lege sustene.","also":["contract","contracts","cuntratti"],"noTip":1},{"id":"sow","g":"money","word":"Descrizzione di u travagliu (SOW)","text":"Un ducumentu chì dice esattamente ciò chì serà fattu, per quandu è per quantu.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Prezzu fissu","text":"Un prezzu cunvenutu per tuttu u travagliu, quantu ch'ellu duri.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Tempu è materiali","text":"Pagà l'ore veramente travagliate è e cose veramente usate, invece d'un prezzu fissu.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Fattura","text":"Un cuntu chì dumanda u pagamentu per un travagliu fattu o merchi furnite.","also":["invoice","invoices","fatture"],"noTip":1},{"id":"lockin","g":"money","word":"Dipendenza da u furnitore (Lock-in)","text":"Quandu lascià un furnitore hè tantu difficiule o caru chì ci sì ligatu.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Appruvvisiunamentu","text":"U prucessu di sceglie è cumprà da i furnitori.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Creditu di serviziu","text":"Soldi rimborsati o una riduzzione chì tù ricevi quandu un furnitore ùn rispetta micca u so SLA.","also":["service credit","service credits"]}]}};
